@Injectable()
export class MonthlyReportExportService {
  templatePath(kind: WorkbookKind, version = '2026.09'): string {
    const candidates = [
      path.resolve(
        process.cwd(),
        'templates',
        'xlsx',
        'monthly-reports',
        version,
        TEMPLATE_FILES[kind],
      ),
      path.resolve(
        __dirname,
        '../../../templates/xlsx/monthly-reports',
        version,
        TEMPLATE_FILES[kind],
      ),
    ];
    return (
      candidates.find((candidate) => fs.existsSync(candidate)) ?? candidates[0]
    );
  }

  async render(
    kind: WorkbookKind,
    snapshot: MonthlyReportSnapshot,
  ): Promise<Buffer> {
    for (const appendix of snapshot.appendices) {
      if (appendix.rows.length > 1_048_540)
        throw new BadRequestException(
          `${appendix.code} vượt giới hạn dòng của một sheet Excel`,
        );
    }
    const template = this.templatePath(kind, snapshot.templateVersion);
    if (!fs.existsSync(template))
      throw new ServiceUnavailableException(`Thiếu mẫu báo cáo tháng ${kind}`);
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.readFile(template);
    if (kind === 'DETAIL') this.fillDetail(workbook, snapshot);
    else this.fillSummary(workbook, snapshot);
    return Buffer.from(await workbook.xlsx.writeBuffer());
  }

  private fillDetail(
    workbook: ExcelJS.Workbook,
    snapshot: MonthlyReportSnapshot,
  ): void {
    for (let index = 0; index < 6; index += 1) {
      const appendix = snapshot.appendices.find(
        (item) => item.code === `PL0${index + 1}`,
      );
      const sheet = workbook.worksheets[index];
      if (!appendix || !sheet) continue;
      sheet.getCell('A1').value = snapshot.unitName;
      sheet.getCell(index < 4 ? 'H2' : 'D2').value =
        `Mốc thời gian: tính đến ngày ${this.viDate(snapshot.periodEnd)}`;
      const startRow = index < 4 ? 6 : 7;
      this.ensureRows(sheet, startRow, appendix.rows.length, 3);
      const keys = DETAIL_COLUMNS[appendix.code] ?? [];
      appendix.rows.forEach((item, rowIndex) => {
        const row = sheet.getRow(startRow + rowIndex);
        row.getCell(1).value = rowIndex + 1;
        keys.forEach((key, columnIndex) => {
          row.getCell(columnIndex + 2).value = item.cells[key] ?? '';
        });
      });
    }
  }

  private ensureRows(
    sheet: ExcelJS.Worksheet,
    startRow: number,
    required: number,
    placeholders: number,
  ): void {
    if (required <= placeholders) return;
    const templateRow = sheet.getRow(startRow + placeholders - 1);
    const extra = required - placeholders;
    // Shift signature/formula rows once; repeated insertRow shifts the entire
    // remaining sheet for every record and becomes quadratic on large reports.
    sheet.insertRows(
      startRow + placeholders,
      Array.from({ length: extra }, () => []),
    );
    for (let i = 0; i < extra; i += 1) {
      const inserted = sheet.getRow(startRow + placeholders + i);
      inserted.height = templateRow.height;
      templateRow.eachCell({ includeEmpty: true }, (cell, column) => {
        inserted.getCell(column).style = { ...cell.style };
      });
    }
  }

  private fillSummary(
    workbook: ExcelJS.Workbook,
    snapshot: MonthlyReportSnapshot,
  ): void {
    for (const code of ['PL07', 'PL08'] as const) {
      const appendix = snapshot.appendices.find((item) => item.code === code);
      const sheet = workbook.worksheets[code === 'PL07' ? 0 : 1];
      if (!appendix || !sheet) continue;
      sheet.getCell('A1').value = snapshot.unitName;
      sheet.getCell(code === 'PL07' ? 'B2' : 'C2').value =
        `Mốc thời gian: từ ngày ${this.viDate(snapshot.periodStart)} đến ngày ${this.viDate(snapshot.periodEnd)}`;
      for (const item of appendix.metrics) {
        const baseKey = item.key.replace(/\.(case|subject)$/, '');
        const row = (code === 'PL07' ? PL07_ROWS : PL08_ROWS)[baseKey];
        if (!row) continue;
        const column = code === 'PL08' && item.key.endsWith('.subject') ? 5 : 4;
        sheet.getCell(row, column).value = item.value;
      }
    }
  }

  private viDate(value: string): string {
    return new Date(value).toLocaleDateString('vi-VN', {
      timeZone: 'Asia/Ho_Chi_Minh',
    });
  }
}

import {
  Body,
  Controller,
  ForbiddenException,
  Get,
  Param,
  Post,
  Query,
  Req,
  Res,
  UseGuards,
} from '@nestjs/common';
import { Throttle } from '@nestjs/throttler';
import {
  IsArray,
  IsDefined,
  IsIn,
  IsOptional,
  IsString,
  MinLength,
} from 'class-validator';
import type { Request, Response } from 'express';
import { AuditService } from '../../audit/audit.service';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import type { DataScope } from '../../auth/services/unit-scope.service';
import { IsNgayThat } from '../../common/validators/is-ngay-that.validator';
import { chonToBaoCao, duocXemBanNhap, phamViTo } from '../tdac/tdac-pham-vi';
import { MonthlyReportPackageService } from './monthly-report-package.service';
import type { MonthlyReportStatus } from './monthly-report.rules';

class CreateMonthlyReportDto {
  @IsNgayThat() periodStart: string;
  @IsNgayThat() periodEnd: string;
  @IsOptional() @IsString() unitCode?: string;
  @IsString() @MinLength(1) unitName: string;
  @IsArray() @IsString({ each: true }) teamIds: string[] = [];
  @IsOptional() @IsString() templateVersion?: string;
}

class TransitionDto {
  @IsOptional() @IsString() reason?: string;
}
class AdjustmentDto {
  @IsString() appendix: string;
  @IsString() targetKey: string;
  @IsOptional() @IsString() entityId?: string;
  @IsIn(['ADD', 'REMOVE', 'REPLACE', 'CONFIRM']) operation: string;
  @IsOptional() previousValue?: unknown;
  @IsDefined() newValue: unknown;
  @IsString() @MinLength(3) reason: string;
  @IsDefined() evidence: unknown;
  @IsOptional() @IsString() issueCode?: string;
}

interface AuthenticatedRequest extends Request {
  user: { id: string };
  dataScope?: DataScope | null;
}

@Controller('reports/monthly-packages')
@UseGuards(JwtAuthGuard, PermissionsGuard)
export class MonthlyReportPackageController {
  constructor(
    private readonly service: MonthlyReportPackageService,
    private readonly audit: AuditService,
  ) {}

  @Post()
  @RequirePermissions({ action: 'write', subject: 'Report' })
  async create(
    @Body() dto: CreateMonthlyReportDto,
    @Req() req: AuthenticatedRequest,
  ) {
    const teamIds = chonToBaoCao(
      dto.teamIds,
      phamViTo(req.dataScope, 'write'),
      'write',
    );
    const report = await this.service.create({ ...dto, teamIds }, req.user.id);
    await this.log(req, 'MONTHLY_REPORT_CREATED', report.id, {
      version: report.version,
      periodStart: report.periodStart,
      periodEnd: report.periodEnd,
    });
    return report;
  }

  @Get()
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  async list(@Req() req: AuthenticatedRequest) {
    const reports = await this.service.list();
    const scope = phamViTo(req.dataScope, 'read');
    return reports
      .filter((report) => duocXemBanNhap(report, req.user.id, scope))
      .slice(0, 100);
  }

  @Get(':id')
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  async get(@Param('id') id: string, @Req() req: AuthenticatedRequest) {
    await this.authorized(id, req, 'read');
    return this.service.get(id);
  }

  @Get(':id/appendices/:code')
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  async appendix(
    @Param('id') id: string,
    @Param('code') code: string,
    @Req() req: AuthenticatedRequest,
  ) {
    await this.authorized(id, req, 'read');
    return this.service.appendix(id, code);
  }

  @Get(':id/drilldown')
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  async drilldown(
    @Param('id') id: string,
    @Req() req: AuthenticatedRequest,
    @Query('appendix') appendix: string,
    @Query('metricKey') metricKey: string,
    @Query('cellKey') cellKey?: string,
    @Query('entityId') entityId?: string,
    @Query('q') q?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    await this.authorized(id, req, 'read');
    return this.service.drilldown(id, {
      appendix,
      metricKey,
      cellKey,
      entityId,
      q,
      page: Number(page) || 1,
      limit: Number(limit) || 20,
    });
  }

  @Post(':id/submit')
  @RequirePermissions({ action: 'write', subject: 'Report' })
  transitionSubmit(@Param('id') id: string, @Req() req: AuthenticatedRequest) {
    return this.doTransition(id, 'REVIEWING', req);
  }
  @Post(':id/approve')
  @RequirePermissions({ action: 'approve', subject: 'Report' })
  transitionApprove(@Param('id') id: string, @Req() req: AuthenticatedRequest) {
    return this.doTransition(id, 'APPROVED', req);
  }
  @Post(':id/finalize')
  @RequirePermissions({ action: 'approve', subject: 'Report' })
  transitionFinalize(
    @Param('id') id: string,
    @Req() req: AuthenticatedRequest,
  ) {
    return this.doTransition(id, 'FINALIZED', req);
  }
  @Post(':id/reject')
  @RequirePermissions({ action: 'approve', subject: 'Report' })
  transitionReject(
    @Param('id') id: string,
    @Req() req: AuthenticatedRequest,
    @Body() dto: TransitionDto,
  ) {
    return this.doTransition(id, 'REJECTED', req, dto.reason);
  }
  @Post(':id/reopen')
  @RequirePermissions({ action: 'write', subject: 'Report' })
  transitionReopen(@Param('id') id: string, @Req() req: AuthenticatedRequest) {
    return this.doTransition(id, 'DRAFT', req);
  }

  @Post(':id/adjustments')
  @RequirePermissions({ action: 'write', subject: 'Report' })
  async adjustment(
    @Param('id') id: string,
    @Req() req: AuthenticatedRequest,
    @Body() dto: AdjustmentDto,
  ) {
    await this.authorized(id, req, 'write');
    const result = await this.service.addAdjustment(id, dto, req.user.id);
    await this.log(req, 'MONTHLY_REPORT_ADJUSTED', id, {
      appendix: dto.appendix,
      targetKey: dto.targetKey,
      operation: dto.operation,
      issueCode: dto.issueCode,
    });
    return result;
  }

  @Get(':id/export/:kind')
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  @Throttle({ default: { ttl: 60_000, limit: 5 } })
  async export(
    @Param('id') id: string,
    @Param('kind') kind: string,
    @Req() req: AuthenticatedRequest,
    @Res() res: Response,
  ) {
    await this.authorized(id, req, 'read');
    if (!['detail', 'summary'].includes(kind))
      throw new ForbiddenException('Loại tệp không hợp lệ');
    const buffer = await this.service.workbook(
      id,
      kind === 'detail' ? 'DETAIL' : 'SUMMARY',
    );
    await this.log(req, 'MONTHLY_REPORT_EXPORTED', id, { kind });
    res.setHeader(
      'Content-Type',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    );
    res.setHeader(
      'Content-Disposition',
      `attachment; filename="bao-cao-thang-${kind}.xlsx"`,
    );
    res.send(buffer);
  }

  @Get(':id/verification')
  @RequirePermissions(
    { action: 'read', subject: 'Case' },
    { action: 'read', subject: 'Incident' },
  )
  @Throttle({ default: { ttl: 60_000, limit: 5 } })
  async verification(
    @Param('id') id: string,
    @Req() req: AuthenticatedRequest,
    @Res() res: Response,
  ) {
    await this.authorized(id, req, 'read');
    const data = await this.service.verification(id);
    await this.log(req, 'MONTHLY_REPORT_VERIFICATION_EXPORTED', id);
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader(
      'Content-Disposition',
      'attachment; filename="goi-kiem-chung-bao-cao.json"',
    );
    res.send(JSON.stringify(data, null, 2));
  }

  private async doTransition(
    id: string,
    next: MonthlyReportStatus,
    req: AuthenticatedRequest,
    reason?: string,
  ) {
    await this.authorized(
      id,
      req,
      next === 'APPROVED' || next === 'FINALIZED' || next === 'REJECTED'
        ? 'read'
        : 'write',
    );
    const report = await this.service.transition(id, next, req.user.id, reason);
    await this.log(req, 'MONTHLY_REPORT_STATUS_CHANGED', id, { next, reason });
    return report;
  }
  private async authorized(
    id: string,
    req: AuthenticatedRequest,
    mode: 'read' | 'write',
  ) {
    const report = await this.service.getAccess(id);
    if (!duocXemBanNhap(report, req.user.id, phamViTo(req.dataScope, mode)))
      throw new ForbiddenException('Bạn không có quyền với gói báo cáo này');
    return report;
  }
  private log(
    req: AuthenticatedRequest,
    action: string,
    subjectId: string,
    metadata?: Record<string, unknown>,
  ) {
    return this.audit.log({
      userId: req.user.id,
      action,
      subject: 'MonthlyReportPackage',
      subjectId,
      metadata,
      ipAddress: req.ip,
      userAgent: req.get('user-agent'),
    });
  }
}

