} from '@nestjs/common';
import { Throttle } from '@nestjs/throttler';
import type { Response } from 'express';
import { IsInt, IsOptional, IsString, Min, Max } from 'class-validator';
import { Type } from 'class-transformer';
import { JwtAuthGuard } from '../../auth/guards/jwt-auth.guard';
import { PermissionsGuard } from '../../auth/guards/permissions.guard';
import { RequirePermissions } from '../../auth/decorators/permissions.decorator';
import type { ScopedRequest } from '../../auth/interfaces/scoped-request.interface';
import { PhuLuc16Service } from './phu-luc-1-6.service';
import { PhuLuc16ExportService } from './phu-luc-1-6-export.service';
import { IsNgayThat } from '../../common/validators/is-ngay-that.validator';

// ─────────────────────────────────────────────────────────────────────────────
// DTO
// ─────────────────────────────────────────────────────────────────────────────

class PhuLuc16QueryDto {
  @IsInt()
  @Min(1)
  @Max(6)
  @Type(() => Number)
  loai!: number;

  @IsOptional()
  @IsNgayThat()
  fromDate?: string;

  @IsOptional()
  @IsNgayThat()
  toDate?: string;

  @IsOptional()
  @IsString()
  unit?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Controller
// ─────────────────────────────────────────────────────────────────────────────

@Controller('reports/phu-luc-1-6')
@UseGuards(JwtAuthGuard, PermissionsGuard)
export class PhuLuc16Controller {
  constructor(
    private readonly phuLuc16Service: PhuLuc16Service,
    private readonly phuLuc16ExportService: PhuLuc16ExportService,
  ) {}

  /**
   * GET /api/v1/reports/phu-luc-1-6/preview?loai=1&fromDate=&toDate=&unit=
   *
   * Returns JSON preview data: { total, data, limited }
   */
  @Get('preview')
  @RequirePermissions({ action: 'read', subject: 'Case' })
  async preview(
    @Query() query: PhuLuc16QueryDto,
    @Req() _req: ScopedRequest,
  ) {
    return this.phuLuc16Service.getForLoai(query.loai, {
      loai: query.loai,
      fromDate: query.fromDate,
      toDate: query.toDate,
      unit: query.unit,
    });
  }

  /**
   * GET /api/v1/reports/phu-luc-1-6/export?loai=1&fromDate=&toDate=&unit=
   *
   * Streams an Excel (.xlsx) file for the requested Phụ lục type.
   * Rate-limited to 3 requests per minute.
   */
  @Get('export')
  @Throttle({ default: { ttl: 60000, limit: 3 } })
  @RequirePermissions({ action: 'read', subject: 'Case' })
  async export(
    @Query() query: PhuLuc16QueryDto,
    @Req() _req: ScopedRequest,
    @Res() res: Response,
  ) {
    const result = await this.phuLuc16Service.getForLoai(query.loai, {
      loai: query.loai,
      fromDate: query.fromDate,
      toDate: query.toDate,
      unit: query.unit,
    });

    await this.phuLuc16ExportService.export(query.loai, result.data, res);
  }
}

import { Module } from '@nestjs/common';
import { PhuLuc16Controller } from './phu-luc-1-6.controller';
import { PhuLuc16Service } from './phu-luc-1-6.service';
import { PhuLuc16ExportService } from './phu-luc-1-6-export.service';
import { PrismaModule } from '../../prisma/prisma.module';
import { AuthModule } from '../../auth/auth.module';

@Module({
  imports: [PrismaModule, AuthModule],
  controllers: [PhuLuc16Controller],
  providers: [PhuLuc16Service, PhuLuc16ExportService],
  exports: [PhuLuc16Service, PhuLuc16ExportService],
})
export class PhuLuc16Module {}

/* eslint-disable @typescript-eslint/no-unsafe-assignment */
/* eslint-disable @typescript-eslint/no-unsafe-member-access */
/**
 * PhuLuc16Service Unit Tests
 *
 * 1. getForLoai(1) calls the correct Prisma method for incidents
 * 2. getForLoai(4) includes subjects and actionPlans
 * 3. Invalid loai returns empty data gracefully
 * 4. fromDate > toDate still executes (validation is at controller layer)
 * 5. Limit 500 is applied
 * 6. PL4 maps multi-subject case to multiple rows (via service data shape)
 */

import { Test, TestingModule } from '@nestjs/testing';
import { PhuLuc16Service } from './phu-luc-1-6.service';
import { PrismaService } from '../../prisma/prisma.service';

// ─── Mock Prisma ──────────────────────────────────────────────────────────────

const mockPrisma = {
  incident: {
    findMany: jest.fn().mockResolvedValue([]),
    count: jest.fn().mockResolvedValue(0),
  },
  case: {
    findMany: jest.fn().mockResolvedValue([]),
    count: jest.fn().mockResolvedValue(0),
  },
};

// ─── Factories ────────────────────────────────────────────────────────────────

function makeIncident(overrides: Record<string, unknown> = {}) {
  return {
    id: 'inc-001',
    code: 'VV-2026-00001',
    name: 'Vụ việc test',
    status: 'TIEP_NHAN',
    doiTuongCaNhan: 'Nguyễn Văn X',
    diaChiXayRa: 'Quận 1',
    incidentType: 'Trộm cắp',
    createdAt: new Date('2026-01-15'),
    deletedAt: null,
    actionPlans: [],
    ...overrides,
  };
}

function makeCase(overrides: Record<string, unknown> = {}, subjects: any[] = []) {
  return {
    id: 'case-abcdef12',
    name: 'Vụ án test',
    status: 'DANG_DIEU_TRA',
    crime: 'Cướp có vũ trang',
    unit: 'Đội 1',
    createdAt: new Date('2026-02-01'),
    deadline: new Date('2026-08-01'),
    deletedAt: null,
    subjects,
    actionPlans: [],
    ...overrides,
  };
}

function makeSubject(overrides: Record<string, unknown> = {}) {
  return {
    id: 'subj-001',
    fullName: 'Trần Văn Y',
    dateOfBirth: new Date('1990-05-10'),
    address: '123 Nguyễn Trãi, Quận 5',
    crimeId: 'crime-001',
    type: 'SUSPECT',
    deletedAt: null,
    ...overrides,
  };
}

// ─── Test Suite ───────────────────────────────────────────────────────────────

describe('PhuLuc16Service', () => {
  let service: PhuLuc16Service;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        PhuLuc16Service,
        { provide: PrismaService, useValue: mockPrisma },
      ],
    }).compile();

    service = module.get<PhuLuc16Service>(PhuLuc16Service);
    jest.clearAllMocks();
    // Reset default return values after clearAllMocks
    mockPrisma.incident.findMany.mockResolvedValue([]);
    mockPrisma.incident.count.mockResolvedValue(0);
    mockPrisma.case.findMany.mockResolvedValue([]);
    mockPrisma.case.count.mockResolvedValue(0);
  });

  // ── Test 1: getForLoai(1) uses incident.findMany ───────────────────────────

  it('getForLoai(1) calls incident.findMany (not case.findMany)', async () => {
    mockPrisma.incident.findMany.mockResolvedValue([makeIncident()]);
    mockPrisma.incident.count.mockResolvedValue(1);

    const result = await service.getForLoai(1, { loai: 1 });

    expect(mockPrisma.incident.findMany).toHaveBeenCalledTimes(1);
    expect(mockPrisma.case.findMany).not.toHaveBeenCalled();
    expect(result.data).toHaveLength(1);
    expect(result.total).toBe(1);
    expect(result.limited).toBe(false);
  });

  // ── Test 2: getForLoai(4) includes subjects and actionPlans ───────────────

  it('getForLoai(4) includes subjects (SUSPECT only) and actionPlans', async () => {
    mockPrisma.case.findMany.mockResolvedValue([
      makeCase({}, [makeSubject()]),
    ]);
    mockPrisma.case.count.mockResolvedValue(1);

    await service.getForLoai(4, { loai: 4 });

    expect(mockPrisma.case.findMany).toHaveBeenCalledTimes(1);
    const callArgs = mockPrisma.case.findMany.mock.calls[0][0];

    // Verify includes
    expect(callArgs.include).toBeDefined();
    expect(callArgs.include.subjects).toBeDefined();
    expect(callArgs.include.subjects.where).toMatchObject({
      deletedAt: null,
      type: 'SUSPECT',
    });
    expect(callArgs.include.actionPlans).toBe(true);
  });

  // ── Test 3: Invalid loai returns empty data gracefully ────────────────────

  it('getForLoai with invalid loai (e.g. 99) returns empty result without throwing', async () => {
    const result = await service.getForLoai(99, { loai: 99 });

    expect(result.total).toBe(0);
    expect(result.data).toEqual([]);
    expect(result.limited).toBe(false);
    // Should not have called Prisma at all
    expect(mockPrisma.incident.findMany).not.toHaveBeenCalled();
    expect(mockPrisma.case.findMany).not.toHaveBeenCalled();
  });

  // ── Test 4: fromDate > toDate still executes (no service-level validation) ─

  it('fromDate > toDate still executes without throwing (controller validates)', async () => {
    mockPrisma.incident.findMany.mockResolvedValue([]);
    mockPrisma.incident.count.mockResolvedValue(0);

    // fromDate after toDate — service should not throw, just pass dates to Prisma
    await expect(
      service.getForLoai(1, {
        loai: 1,
        fromDate: '2026-12-31',
        toDate: '2026-01-01',
      }),
    ).resolves.toBeDefined();

    expect(mockPrisma.incident.findMany).toHaveBeenCalledTimes(1);
  });

  // ── Test 5: Default limit of 500 is applied ───────────────────────────────

  it('applies default limit of 500 when no limit is specified', async () => {
    mockPrisma.incident.findMany.mockResolvedValue([]);
    mockPrisma.incident.count.mockResolvedValue(0);

    await service.getForLoai(1, { loai: 1 });

    const callArgs = mockPrisma.incident.findMany.mock.calls[0][0];
    expect(callArgs.take).toBe(500);
  });

  it('respects custom limit when provided', async () => {
    mockPrisma.case.findMany.mockResolvedValue([]);
    mockPrisma.case.count.mockResolvedValue(0);

    await service.getForLoai(4, { loai: 4, limit: 100 });

    const callArgs = mockPrisma.case.findMany.mock.calls[0][0];
    expect(callArgs.take).toBe(100);
  });

  // ── Test 6: PL4 data shape supports multi-subject expansion ───────────────
  // The service returns raw Prisma objects (with subjects[]).
  // The export service is responsible for expanding to one row per subject.
  // This test verifies that the service preserves the subjects array intact.

  it('getForLoai(4) preserves multi-subject data so export service can expand rows', async () => {
    const twoSubjectCase = makeCase({}, [
      makeSubject({ id: 'subj-A', fullName: 'Bị can A' }),
      makeSubject({ id: 'subj-B', fullName: 'Bị can B' }),
    ]);
    mockPrisma.case.findMany.mockResolvedValue([twoSubjectCase]);
    mockPrisma.case.count.mockResolvedValue(1);

    const result = await service.getForLoai(4, { loai: 4 });

    // Service returns 1 case record with 2 subjects — expansion is done in export
    expect(result.data).toHaveLength(1);
    expect(result.data[0].subjects).toHaveLength(2);
    expect(result.data[0].subjects[0].fullName).toBe('Bị can A');
    expect(result.data[0].subjects[1].fullName).toBe('Bị can B');
  });
});

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CaseStatus, IncidentStatus } from '@prisma/client';

// ─────────────────────────────────────────────────────────────────────────────
// Shared param type used by all 6 Phụ lục methods
// ─────────────────────────────────────────────────────────────────────────────

export interface PhuLuc16Params {
  loai: number;
  fromDate?: string;
  toDate?: string;
  unit?: string;
  limit?: number;
}

// Return shape that the export service and controller consume
export interface PhuLuc16Result {
  total: number;
  data: any[];
  limited: boolean;
}

// Statuses that indicate an Incident is under TĐC (tạm đình chỉ)
const INCIDENT_TDC_STATUSES: IncidentStatus[] = [
  IncidentStatus.TAM_DINH_CHI,
  IncidentStatus.TDC_HET_THOI_HIEU,
  IncidentStatus.TDC_HTH_KHONG_KT,
];

// Statuses that indicate an Incident is still active (not TĐC, not closed)
const INCIDENT_ACTIVE_EXCLUDED: IncidentStatus[] = [
  IncidentStatus.TAM_DINH_CHI,
  IncidentStatus.TDC_HET_THOI_HIEU,
  IncidentStatus.TDC_HTH_KHONG_KT,
  IncidentStatus.DA_GIAI_QUYET,
  IncidentStatus.DA_CHUYEN_VU_AN,
  IncidentStatus.KHONG_KHOI_TO,
  IncidentStatus.CHUYEN_XPHC,
  IncidentStatus.DA_CHUYEN_DON_VI,
  IncidentStatus.DA_NHAP_VU_KHAC,
  IncidentStatus.PHAN_LOAI_DAN_SU,
];

// Case statuses excluded from "active" (PL4)
const CASE_ACTIVE_EXCLUDED: CaseStatus[] = [
  CaseStatus.TAM_DINH_CHI,
  CaseStatus.DINH_CHI,
  CaseStatus.DA_LUU_TRU,
  CaseStatus.DA_KET_LUAN,
];

@Injectable()
export class PhuLuc16Service {
  constructor(private readonly prisma: PrismaService) {}

  // ── Helpers ───────────────────────────────────────────────────────────────

  private _dateRange(fromDate?: string, toDate?: string) {
    const gte = fromDate ? new Date(fromDate) : undefined;
    const lte = toDate ? new Date(toDate + 'T23:59:59.999Z') : undefined;
    if (!gte && !lte) return undefined;
    return { ...(gte ? { gte } : {}), ...(lte ? { lte } : {}) };
  }

  // ── PL1: Active Incidents (not TĐC) ──────────────────────────────────────

  async getPL1(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.incident.findMany({
      where: {
        deletedAt: null,
        status: { notIn: INCIDENT_ACTIVE_EXCLUDED },
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
      include: {
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    // Count without limit to determine if result was capped
    const total = await this.prisma.incident.count({
      where: {
        deletedAt: null,
        status: { notIn: INCIDENT_ACTIVE_EXCLUDED },
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── PL2: TĐC Incidents where time-limit has expired (ngayHetThoiHieuVV < now) ──

  async getPL2(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const now = new Date();
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.incident.findMany({
      where: {
        deletedAt: null,
        status: { in: INCIDENT_TDC_STATUSES },
        OR: [
          { ngayHetThoiHieuVV: { lt: now } },
          { ngayHetThoiHieuVV: null, deadline: { lt: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
      include: {
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    const total = await this.prisma.incident.count({
      where: {
        deletedAt: null,
        status: { in: INCIDENT_TDC_STATUSES },
        OR: [
          { ngayHetThoiHieuVV: { lt: now } },
          { ngayHetThoiHieuVV: null, deadline: { lt: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── PL3: TĐC Incidents where time-limit is still valid (ngayHetThoiHieuVV >= now) ──

  async getPL3(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const now = new Date();
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.incident.findMany({
      where: {
        deletedAt: null,
        status: { in: INCIDENT_TDC_STATUSES },
        OR: [
          { ngayHetThoiHieuVV: { gte: now } },
          { ngayHetThoiHieuVV: null, deadline: { gte: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
      include: {
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    const total = await this.prisma.incident.count({
      where: {
        deletedAt: null,
        status: { in: INCIDENT_TDC_STATUSES },
        OR: [
          { ngayHetThoiHieuVV: { gte: now } },
          { ngayHetThoiHieuVV: null, deadline: { gte: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unitId: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── PL4: Active Cases (not TĐC/ĐÌNH CHỈ/LƯU TRỮ/KẾT LUẬN) ─────────────

  async getPL4(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.case.findMany({
      where: {
        deletedAt: null,
        status: { notIn: CASE_ACTIVE_EXCLUDED },
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
      include: {
        subjects: {
          where: { deletedAt: null, type: 'SUSPECT' },
        },
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    const total = await this.prisma.case.count({
      where: {
        deletedAt: null,
        status: { notIn: CASE_ACTIVE_EXCLUDED },
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── PL5: TĐC Cases where time-limit has expired (ngayHetThoiHieu < now) ──

  async getPL5(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const now = new Date();
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.case.findMany({
      where: {
        deletedAt: null,
        status: CaseStatus.TAM_DINH_CHI,
        OR: [
          { ngayHetThoiHieu: { lt: now } },
          { ngayHetThoiHieu: null, deadline: { lt: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
      include: {
        subjects: {
          where: { deletedAt: null, type: 'SUSPECT' },
        },
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    const total = await this.prisma.case.count({
      where: {
        deletedAt: null,
        status: CaseStatus.TAM_DINH_CHI,
        OR: [
          { ngayHetThoiHieu: { lt: now } },
          { ngayHetThoiHieu: null, deadline: { lt: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── PL6: TĐC Cases where time-limit is still valid (ngayHetThoiHieu >= now) ──

  async getPL6(params: PhuLuc16Params): Promise<PhuLuc16Result> {
    const limit = params.limit ?? 500;
    const now = new Date();
    const dateRange = this._dateRange(params.fromDate, params.toDate);

    const data = await this.prisma.case.findMany({
      where: {
        deletedAt: null,
        status: CaseStatus.TAM_DINH_CHI,
        OR: [
          { ngayHetThoiHieu: { gte: now } },
          { ngayHetThoiHieu: null, deadline: { gte: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
      include: {
        subjects: {
          where: { deletedAt: null, type: 'SUSPECT' },
        },
        actionPlans: true,
      },
      orderBy: { createdAt: 'asc' },
      take: limit,
    });

    const total = await this.prisma.case.count({
      where: {
        deletedAt: null,
        status: CaseStatus.TAM_DINH_CHI,
        OR: [
          { ngayHetThoiHieu: { gte: now } },
          { ngayHetThoiHieu: null, deadline: { gte: now } },
        ],
        ...(dateRange ? { createdAt: dateRange } : {}),
        ...(params.unit ? { unit: params.unit } : {}),
      },
    });

    return { total, data, limited: total > limit };
  }

  // ── Dispatcher ─────────────────────────────────────────────────────────────

  async getForLoai(
    loai: number,
    params: PhuLuc16Params,
  ): Promise<PhuLuc16Result> {
    switch (loai) {
      case 1:
        return this.getPL1(params);
      case 2:
        return this.getPL2(params);
      case 3:
        return this.getPL3(params);
      case 4:
        return this.getPL4(params);
      case 5:
        return this.getPL5(params);
      case 6:
        return this.getPL6(params);
      default:
        return { total: 0, data: [], limited: false };
    }
  }
}

