/**
 * ReportsExportService Unit Tests
 *
 * Covers the export methods and critical edge cases:
 * - Stat48 export: worksheet name sanitization (colon/special chars crash ExcelJS)
 * - Monthly/Quarterly export: response headers and stream write
 */

import { ReportsExportService } from './reports-export.service';

// ─── Mock ExcelJS ─────────────────────────────────────────────────────────────

const mockSheet = {
  mergeCells: jest.fn(),
  getCell: jest.fn().mockReturnValue({
    value: null,
    font: {},
    fill: {},
    alignment: {},
    border: {},
  }),
  getRow: jest.fn().mockReturnValue({
    getCell: jest.fn().mockReturnValue({ value: null, font: {}, fill: {}, alignment: {}, border: {} }),
    height: 0,
  }),
  columns: [],
};

const mockWorkbook = {
  addWorksheet: jest.fn().mockReturnValue(mockSheet),
  xlsx: {
    write: jest.fn().mockResolvedValue(undefined),
  },
};

jest.mock('exceljs', () => ({
  Workbook: jest.fn().mockImplementation(() => mockWorkbook),
}));

// ─── Mock Response ────────────────────────────────────────────────────────────

function makeRes() {
  return {
    setHeader: jest.fn(),
    status: jest.fn().mockReturnThis(),
    json: jest.fn(),
    headersSent: false,
    destroy: jest.fn(),
  } as any;
}

// ─── Test Suite ───────────────────────────────────────────────────────────────

describe('ReportsExportService', () => {
  let service: ReportsExportService;

  beforeEach(() => {
    service = new ReportsExportService();
    jest.clearAllMocks();
    // Re-setup mocks after clear
    mockSheet.getCell.mockReturnValue({ value: null, font: {}, fill: {}, alignment: {}, border: {} });
    mockSheet.getRow.mockReturnValue({
      getCell: jest.fn().mockReturnValue({ value: null, font: {}, fill: {}, alignment: {}, border: {} }),
      height: 0,
    });
    mockWorkbook.addWorksheet.mockReturnValue(mockSheet);
    mockWorkbook.xlsx.write.mockResolvedValue(undefined);
  });

  // ── exportStat48 ────────────────────────────────────────────────────────────

  describe('exportStat48', () => {
    const baseStat48 = {
      totalCases: 10,
      nullCount: 2,
      nullRatePct: 20,
      isDraft: false,
      fromDate: '2025-01-01',
      toDate: '2025-12-31',
      groups: [],
    };

    it('sanitizes worksheet name: strips colon from group name', async () => {
      const data = {
        ...baseStat48,
        groups: [{ name: 'Nhóm 1: Nguồn tin', fields: [] }],
      };

      await service.exportStat48(data as any, makeRes());

      const sheetName = mockWorkbook.addWorksheet.mock.calls[0][0];
      // Colon must be replaced with dash, not kept
      expect(sheetName).not.toContain(':');
      expect(sheetName).toBe('Nhóm 1- Nguồn tin');
    });

    it('sanitizes worksheet name: strips all ExcelJS-illegal chars (* ? : \\ / [ ])', async () => {
      const data = {
        ...baseStat48,
        groups: [{ name: 'Test*?:/\\[]Sheet', fields: [] }],
      };

      await service.exportStat48(data as any, makeRes());

      const sheetName = mockWorkbook.addWorksheet.mock.calls[0][0];
      expect(sheetName).not.toMatch(/[*?:/\\[\]]/);
    });

    it('truncates worksheet name to 31 characters', async () => {
      const longName = 'A'.repeat(50);
      const data = {
        ...baseStat48,
        groups: [{ name: longName, fields: [] }],
      };

      await service.exportStat48(data as any, makeRes());

      const sheetName = mockWorkbook.addWorksheet.mock.calls[0][0];
      expect(sheetName.length).toBeLessThanOrEqual(31);
    });

    it('creates one worksheet per group', async () => {
      const data = {
        ...baseStat48,
        groups: [
          { name: 'Nhóm 1- Nguồn tin', fields: [] },
          { name: 'Nhóm 2- Tội phạm', fields: [] },
          { name: 'Nhóm 3- Đối tượng', fields: [] },
          { name: 'Nhóm 4- Kết quả', fields: [] },
        ],
      };

      await service.exportStat48(data as any, makeRes());

      expect(mockWorkbook.addWorksheet).toHaveBeenCalledTimes(4);
    });

    it('sets Content-Disposition attachment header', async () => {
      const res = makeRes();
      await service.exportStat48(baseStat48 as any, res);

      expect(res.setHeader).toHaveBeenCalledWith(
        'Content-Disposition',
        expect.stringContaining('attachment'),
      );
    });

    it('appends _DRAFT to filename when isDraft=true', async () => {
      const res = makeRes();
      await service.exportStat48({ ...baseStat48, isDraft: true } as any, res);

      const dispositionCall = res.setHeader.mock.calls.find(
        (c: string[]) => c[0] === 'Content-Disposition',
      );
      expect(dispositionCall[1]).toContain('DRAFT');
    });

    it('does NOT crash when groups array is empty', async () => {
      await expect(
        service.exportStat48(baseStat48 as any, makeRes()),
      ).resolves.not.toThrow();
    });
  });

  // ── exportMonthly ────────────────────────────────────────────────────────────

  describe('exportMonthly', () => {
    const monthlyData = {
      year: 2026,
      month: 2,
      data: [
        { month: 'Tháng 1', donThu: 10, vuViec: 5, vuAn: 3, daGiaiQuyet: 8 },
      ],
      totals: { donThu: 10, vuViec: 5, vuAn: 3, daGiaiQuyet: 8 },
    };

    it('includes month in filename when month is provided', async () => {
      const res = makeRes();
      await service.exportMonthly(monthlyData as any, res);

      const dispositionCall = res.setHeader.mock.calls.find(
        (c: string[]) => c[0] === 'Content-Disposition',
      );
      expect(dispositionCall[1]).toContain('_T2');
    });

    it('omits month from filename when only year provided', async () => {
      const res = makeRes();
      const yearOnly = { ...monthlyData, month: undefined };
      await service.exportMonthly(yearOnly as any, res);

      const dispositionCall = res.setHeader.mock.calls.find(
        (c: string[]) => c[0] === 'Content-Disposition',
      );
      expect(dispositionCall[1]).not.toContain('_T');
    });
  });
});

import { Injectable } from '@nestjs/common';
import { Response } from 'express';
import * as ExcelJS from 'exceljs';
import { BcaExcelHelper } from '../common/bca-excel.helper';

// ─────────────────────────────────────────────────────────────────────────────
// Types matching the shape returned by ReportsService
// ─────────────────────────────────────────────────────────────────────────────

interface MonthlyRow {
  month: string;
  donThu: number;
  vuViec: number;
  vuAn: number;
  daGiaiQuyet: number;
}

interface MonthlyData {
  data: MonthlyRow[];
  totals: { donThu: number; vuViec: number; vuAn: number; daGiaiQuyet: number };
  year: number;
  month?: number;
  /**
   * Nhãn kỳ do máy chủ dựng — có với mọi loại kỳ, kể cả lũy kế và khoảng tự chọn.
   *
   * Trước đây tiêu đề tệp suy từ `month`: có tháng thì "THÁNG N", không thì "NĂM". Nên tệp xuất
   * cho "lũy kế 8 tháng" dán nhãn CẢ NĂM trong khi dòng tổng chỉ là 8 tháng — một tệp tự mâu
   * thuẫn, và người nhận tệp không có màn hình để đối chiếu.
   */
  kyNhan?: string;
}

interface QuarterlyRow {
  quarter: string;
  donThu: number;
  vuViec: number;
  vuAn: number;
  daGiaiQuyet: number;
}

interface QuarterlyData {
  data: QuarterlyRow[];
  totals: { donThu: number; vuViec: number; vuAn: number; daGiaiQuyet: number };
  year: number;
  quarter?: number;
  /** Xem chú thích ở `MonthlyData.kyNhan`. */
  kyNhan?: string;
}

interface Stat48FieldResult {
  field: string;
  type: 'numeric' | 'categorical';
  total?: number;
  distribution?: Record<string, number>;
  dataCount: number;
  nullCount: number;
}

interface Stat48Group {
  name: string;
  fields: Stat48FieldResult[];
}

interface Stat48Data {
  totalCases: number;
  nullCount: number;
  nullRatePct: number;
  isDraft: boolean;
  fromDate: string;
  toDate: string;
  unit?: string;
  groups: Stat48Group[];
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

const NAVY_ARGB = 'FF1B2B4E';
const WHITE_ARGB = 'FFFFFFFF';

function applyNavyHeader(cell: ExcelJS.Cell, text: string) {
  cell.value = text;
  cell.font = { bold: true, color: { argb: WHITE_ARGB }, size: 13 };
  cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY_ARGB } };
  cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
}

function applyColumnHeaders(row: ExcelJS.Row, headers: string[]) {
  headers.forEach((h, i) => {
    const cell = row.getCell(i + 1);
    cell.value = h;
    cell.font = { bold: true, color: { argb: WHITE_ARGB } };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: NAVY_ARGB } };
    cell.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
    cell.border = {
      top: { style: 'thin' }, left: { style: 'thin' },
      bottom: { style: 'thin' }, right: { style: 'thin' },
    };
  });
  row.height = 22;
}

function borderCell(cell: ExcelJS.Cell) {
  cell.border = {
    top: { style: 'thin' }, left: { style: 'thin' },
    bottom: { style: 'thin' }, right: { style: 'thin' },
  };
}

function setXlsxHeaders(res: Response, filename: string) {
  res.setHeader(
    'Content-Type',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  );
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
}

// ─────────────────────────────────────────────────────────────────────────────
// Service
// ─────────────────────────────────────────────────────────────────────────────

@Injectable()
export class ReportsExportService {
  // ── Monthly export ─────────────────────────────────────────────────────────

  async exportMonthly(data: MonthlyData, res: Response): Promise<void> {
    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Báo cáo tháng');
    const COL_COUNT = 6;
    const HEADERS = ['Đơn vị', 'Đơn thư', 'Vụ việc', 'Vụ án', 'Đã giải quyết', 'Tỷ lệ %'];
    const WIDTHS = [20, 12, 12, 12, 16, 12];

    const nhanKy =
      data.kyNhan ?? (data.month ? `Tháng ${data.month}/${data.year}` : `Năm ${data.year}`);
    const title = `BẢNG THỐNG KÊ ${nhanKy.toUpperCase()}`;
    const period = `Kỳ báo cáo: ${nhanKy}`;

    // BCA professional header (rows 1-6)
    BcaExcelHelper.addHeader(sheet, COL_COUNT, title, period);

    // Column headers (row 7)
    BcaExcelHelper.addColumnHeaders(sheet.getRow(7), HEADERS, WIDTHS);
    sheet.getRow(7).height = 22;

    // Data rows (row 8+)
    data.data.forEach((row, idx) => {
      const total = row.donThu + row.vuViec + row.vuAn;
      const tyLe = total > 0 ? Math.round((row.daGiaiQuyet / total) * 100) : 0;
      const excelRow = sheet.getRow(idx + 8);
      const values = [row.month, row.donThu, row.vuViec, row.vuAn, row.daGiaiQuyet, tyLe];
      BcaExcelHelper.styleDataRow(excelRow, idx % 2 === 0, COL_COUNT);
      values.forEach((v, ci) => {
        const cell = excelRow.getCell(ci + 1);
        cell.value = v;
        cell.alignment = { horizontal: ci === 0 ? 'left' : 'center', vertical: 'middle' };
      });
    });

    // Totals row
    const totalsRowIdx = data.data.length + 8;
    const totalsRow = sheet.getRow(totalsRowIdx);
    const grandTotal = data.totals.donThu + data.totals.vuViec + data.totals.vuAn;
    const grandTyLe = grandTotal > 0 ? Math.round((data.totals.daGiaiQuyet / grandTotal) * 100) : 0;
    BcaExcelHelper.styleDataRow(totalsRow, false, COL_COUNT);
    [
      'TỔNG CỘNG',
      data.totals.donThu,
      data.totals.vuViec,
      data.totals.vuAn,
      data.totals.daGiaiQuyet,
      grandTyLe,
    ].forEach((v, ci) => {
      const cell = totalsRow.getCell(ci + 1);
      cell.value = v;
      cell.font = { bold: true, size: 11 };
      cell.alignment = { horizontal: ci === 0 ? 'left' : 'center', vertical: 'middle' };
    });

    // BCA footer
    BcaExcelHelper.addFooter(sheet, totalsRowIdx + 2, COL_COUNT);
    BcaExcelHelper.setPrintSetup(sheet, true);

    const filename = `BaoCaoThang_${data.year}${data.month ? '_T' + data.month : ''}_${Date.now()}.xlsx`;
    setXlsxHeaders(res, filename);
    try { await workbook.xlsx.write(res); } catch (err) { if (!res.headersSent) res.status(500).json({ error: 'Export failed' }); else res.destroy(); }
  }

  // ── Quarterly export ────────────────────────────────────────────────────────

  async exportQuarterly(data: QuarterlyData, res: Response): Promise<void> {
    const workbook = new ExcelJS.Workbook();
    const sheet = workbook.addWorksheet('Báo cáo quý');
    const COL_COUNT = 6;
    const HEADERS = ['Kỳ', 'Đơn thư', 'Vụ việc', 'Vụ án', 'Đã giải quyết', 'Tỷ lệ %'];
    const WIDTHS = [20, 12, 12, 12, 16, 12];

    const nhanKy =
      data.kyNhan ?? (data.quarter ? `Quý ${data.quarter}/${data.year}` : `Năm ${data.year}`);
    const title = `BẢNG THỐNG KÊ ${nhanKy.toUpperCase()}`;
    const period = `Kỳ báo cáo: ${nhanKy}`;

    BcaExcelHelper.addHeader(sheet, COL_COUNT, title, period);
    BcaExcelHelper.addColumnHeaders(sheet.getRow(7), HEADERS, WIDTHS);
    sheet.getRow(7).height = 22;

    data.data.forEach((row, idx) => {
      const total = row.donThu + row.vuViec + row.vuAn;
      const tyLe = total > 0 ? Math.round((row.daGiaiQuyet / total) * 100) : 0;
      const excelRow = sheet.getRow(idx + 8);
      BcaExcelHelper.styleDataRow(excelRow, idx % 2 === 0, COL_COUNT);
      [row.quarter, row.donThu, row.vuViec, row.vuAn, row.daGiaiQuyet, tyLe].forEach((v, ci) => {
        const cell = excelRow.getCell(ci + 1);
        cell.value = v;
        cell.alignment = { horizontal: ci === 0 ? 'left' : 'center', vertical: 'middle' };
      });
    });

    const totalsRowIdx = data.data.length + 8;
    const totalsRow = sheet.getRow(totalsRowIdx);
    const grandTotal = data.totals.donThu + data.totals.vuViec + data.totals.vuAn;
    const grandTyLe = grandTotal > 0 ? Math.round((data.totals.daGiaiQuyet / grandTotal) * 100) : 0;
    BcaExcelHelper.styleDataRow(totalsRow, false, COL_COUNT);
    [
      'TỔNG CỘNG',
      data.totals.donThu,
      data.totals.vuViec,
      data.totals.vuAn,
      data.totals.daGiaiQuyet,
      grandTyLe,
    ].forEach((v, ci) => {
      const cell = totalsRow.getCell(ci + 1);
      cell.value = v;
      cell.font = { bold: true, size: 11 };
      cell.alignment = { horizontal: ci === 0 ? 'left' : 'center', vertical: 'middle' };
    });

    BcaExcelHelper.addFooter(sheet, totalsRowIdx + 2, COL_COUNT);
    BcaExcelHelper.setPrintSetup(sheet, true);

    const filename = `BaoCaoQuy_${data.year}${data.quarter ? '_Q' + data.quarter : ''}_${Date.now()}.xlsx`;
    setXlsxHeaders(res, filename);
    try { await workbook.xlsx.write(res); } catch (err) { if (!res.headersSent) res.status(500).json({ error: 'Export failed' }); else res.destroy(); }
  }

  // ── Stat48 export ───────────────────────────────────────────────────────────

  async exportStat48(data: Stat48Data, res: Response): Promise<void> {
    const workbook = new ExcelJS.Workbook();

    const titleSuffix = data.isDraft ? ' [⚠ DRAFT]' : '';

    data.groups.forEach((group) => {
      // Excel sheet name: max 31 chars, cannot contain * ? : \ / [ ]
      const sheetName = group.name.replace(/[*?:/\\[\]]/g, '-').slice(0, 31);
      const sheet = workbook.addWorksheet(sheetName);

      const COL_COUNT = 5;
      const stat48Title = `THỐNG KÊ 48 TRƯỜNG — ${group.name}${titleSuffix}`;
      const stat48Period = `Từ ngày: ${data.fromDate} — Đến ngày: ${data.toDate}${data.unit ? ` | Đơn vị: ${data.unit}` : ''} | Tổng: ${data.totalCases} | Thiếu: ${data.nullRatePct}%`;
      BcaExcelHelper.addHeader(sheet, COL_COUNT, stat48Title, stat48Period);

      // Row 7: column headers
      BcaExcelHelper.addColumnHeaders(sheet.getRow(7), [
        'Tên trường', 'Loại', 'Tổng/Giá trị', 'Số lượng/Tần suất', 'Thiếu dữ liệu',
      ], [28, 14, 22, 18, 16]);
      sheet.getRow(7).height = 22;

      let rowIdx = 8;

      group.fields.forEach((field) => {
        if (field.type === 'numeric') {
          const row = sheet.getRow(rowIdx++);
          [
            field.field,
            'Số',
            field.total ?? 0,
            field.dataCount,
            field.nullCount,
          ].forEach((v, ci) => {
            const cell = row.getCell(ci + 1);
            cell.value = v;
            borderCell(cell);
            cell.alignment = { vertical: 'middle', horizontal: ci < 2 ? 'left' : 'center' };
          });
        } else {
          // categorical: one row per distribution entry
          const dist = field.distribution ?? {};
          const entries = Object.entries(dist);
          if (entries.length === 0) {
            const row = sheet.getRow(rowIdx++);
            [field.field, 'Phân loại', '(không có dữ liệu)', 0, field.nullCount].forEach(
              (v, ci) => {
                const cell = row.getCell(ci + 1);
                cell.value = v;
                borderCell(cell);
                cell.alignment = { vertical: 'middle', horizontal: ci < 2 ? 'left' : 'center' };
              },
            );
          } else {
            entries.forEach(([value, count], entryIdx) => {
              const row = sheet.getRow(rowIdx++);
              [
                entryIdx === 0 ? field.field : '',
                entryIdx === 0 ? 'Phân loại' : '',
                value,
                count,
                entryIdx === 0 ? field.nullCount : '',
              ].forEach((v, ci) => {
                const cell = row.getCell(ci + 1);
                cell.value = v;
                borderCell(cell);
                cell.alignment = { vertical: 'middle', horizontal: ci < 2 ? 'left' : 'center', wrapText: true };
              });
            });
          }
        }
      });
      BcaExcelHelper.addFooter(sheet, rowIdx + 1, COL_COUNT);
      BcaExcelHelper.setPrintSetup(sheet, true);
    });

    const filename = `Stat48_${data.fromDate}_${data.toDate}${data.isDraft ? '_DRAFT' : ''}_${Date.now()}.xlsx`;
    setXlsxHeaders(res, filename);
    try { await workbook.xlsx.write(res); } catch (err) { if (!res.headersSent) res.status(500).json({ error: "Export failed" }); else res.destroy(); }
  }
}

