import { Injectable, Logger } from '@nestjs/common';
import { TRANG_THAI_KET_THUC } from '../common/trang-thai/trang-thai-ket-thuc';
import {
  dungSoSanh,
  kyThang,
  kyQuy,
  kyNam,
  KIEU_SO_SANH_MAC_DINH,
  kyLuyKe,
  kyTuyChon,
  thangTrongKy,
  quyTrongKy,
  COT_NGAY_TIEP_NHAN,
  MOC_NAM_HOP_LE,
  type KieuSoSanh,
  type Ky,
} from './so-sanh-ky';
import { PrismaService } from '../prisma/prisma.service';
import { CaseStatus, IncidentStatus, PetitionStatus } from '@prisma/client';
import { BoTimKiem } from '../common/tim-kiem/bo-tim-kiem';
import { KHOA_TAT_CA } from '../common/tim-kiem/dieu-kien';
import { kiemTheChung } from '../common/tim-kiem/khoa-chung';
import { KHAI_TIM_KIEM_VU_AN } from '../common/tim-kiem/khai/vu-an.khai';
import { KHAI_TIM_KIEM_VU_VIEC } from '../common/tim-kiem/khai/vu-viec.khai';
import { KHAI_TIM_KIEM_DON_THU } from '../common/tim-kiem/khai/don-thu.khai';

/** Ba loại hồ sơ của màn Hồ sơ trễ hạn — thẻ chỉ nhận "*" và khoá chung của cả ba. */
const KHAI_HO_SO_TRE_HAN = [
  KHAI_TIM_KIEM_VU_AN,
  KHAI_TIM_KIEM_VU_VIEC,
  KHAI_TIM_KIEM_DON_THU,
] as const;
/** `search` cũ → thẻ "tất cả các cột" của từng khai. */
const THAM_SO_CU_TRE_HAN = { search: KHOA_TAT_CA } as const;

interface NguonSoHoSo {
  id: string;
  stt?: string | null;
  caseCode?: string | null;
  code?: string | null;
}

/**
 * Số hồ sơ trên màn Trễ hạn: đơn thư `stt`, vụ án `caseCode`, vụ việc `code` — đúng mã thẻ STT tìm theo.
 * Trước đây `select` không lấy `caseCode`/`code` nên vụ án/vụ việc luôn hiện id cắt 8 ký tự.
 */
function soHoSo(item: NguonSoHoSo): string {
  return (
    item.stt ?? item.caseCode ?? item.code ?? item.id.slice(0, 8).toUpperCase()
  );
}

// ─────────────────────────────────────────────
// Stat48 field definitions
// ─────────────────────────────────────────────

const NUMERIC_FIELDS = new Set([
  'Thiệt hại (VNĐ)',
  'Đã thu hồi (VNĐ)',
  'Số bị hại',
  'Số người chết',
  'Số người bị thương',
  'Số đối tượng',
  'Đã bắt giữ',
  'Đã tạm giam',
  'Số ngày xử lý',
  'Số nhân chứng',
  'Tài sản thu giữ',
  'Chứng cứ thu thập',
]);

const STAT_GROUPS = [
  {
    name: 'Nhóm 1: Nguồn tin',
    fields: [
      'Loại nguồn tin', 'Nguồn gốc', 'Loại người báo tin', 'Hình thức tiếp nhận',
      'Mức độ khẩn', 'Đơn vị tiếp báo', 'Ngày xảy ra vụ việc', 'Giờ xảy ra vụ việc',
      'Tỉnh/Thành phố', 'Quận/Huyện', 'Phường/Xã', 'Phân loại ban đầu',
    ],
  },
  {
    name: 'Nhóm 2: Tội phạm',
    fields: [
      'Tội danh chính', 'Tội danh phụ', 'Lĩnh vực', 'Phương thức thủ đoạn',
      'Thiệt hại (VNĐ)', 'Đã thu hồi (VNĐ)', 'Số bị hại', 'Số người chết',
      'Số người bị thương', 'Thiệt hại tài sản', 'Tội phạm có tổ chức', 'Tái phạm',
    ],
  },
  {
    name: 'Nhóm 3: Đối tượng',
    fields: [
      'Số đối tượng', 'Đã bắt giữ', 'Đã tạm giam', 'Giới tính',
      'Độ tuổi', 'Dân tộc', 'Quốc tịch', 'Nghề nghiệp',
      'Trình độ học vấn', 'Tiền án tiền sự', 'Liên quan ma túy', 'Sử dụng vũ khí',
    ],
  },
  {
    name: 'Nhóm 4: Kết quả',
    fields: [
      'Trạng thái xử lý', 'Kết quả điều tra', 'Kết quả truy tố', 'Kết quả xét xử',
      'Mức án', 'Ngày kết thúc', 'Số ngày xử lý', 'Chứng cứ thu thập',
      'Số nhân chứng', 'Tài sản thu giữ', 'Chuyển vụ án', 'Đã báo cáo',
    ],
  },
];

/**
 * Kỳ báo cáo do người dùng chọn, ngoài "một tháng / một quý / cả năm".
 *
 * `luyKeDenThang` và cặp `tu`/`den` loại trừ nhau — chọn cả hai là mâu thuẫn, và hàm `chonKy`
 * ưu tiên theo thứ tự khai để không im lặng lấy bừa một cái.
 */
export interface TuyChonKy {
  /** Lũy kế từ đầu năm tới hết tháng này. */
  luyKeDenThang?: number;
  /** Khoảng tự chọn cho KỲ ĐANG XEM. */
  tu?: string;
  den?: string;
  /** Khoảng tự chọn cho KỲ NỀN (dùng với `soSanh=TUY_CHON`). */
  nenTu?: string;
  nenDen?: string;
}

/**
 * Quy ước chọn kỳ, dùng chung cho báo cáo tháng và quý.
 *
 * Thứ tự ưu tiên viết thẳng ra đây thay vì rải trong hai hàm: hai bản sao của một quy tắc là
 * hai bản sẽ lệch nhau.
 */
function chonKy(
  nam: number,
  so: number | undefined,
  tuyChon: TuyChonKy | undefined,
  dungTheoSo: (nam: number, so: number) => Ky,
): Ky {
  if (tuyChon?.tu && tuyChon?.den) return kyTuyChon(new Date(tuyChon.tu), new Date(tuyChon.den));
  if (tuyChon?.luyKeDenThang) return kyLuyKe(nam, tuyChon.luyKeDenThang);
  // Không chọn tháng/quý nghĩa là đang xem CẢ NĂM — kỳ nền phải là cả năm trước, không phải
  // tháng 12 hay quý 4 năm trước.
  return so ? dungTheoSo(nam, so) : kyNam(nam);
}

/**
 * Kỳ báo cáo do người dùng chọn, ngoài "một tháng / một quý / cả năm".
 *
 * `luyKeDenThang` và cặp `tu`/`den` loại trừ nhau — chọn cả hai là mâu thuẫn, và hàm `chonKy`
 * ưu tiên theo thứ tự khai để không im lặng lấy bừa một cái.
 */
export interface TuyChonKy {
  /** Lũy kế từ đầu năm tới hết tháng này. */
  luyKeDenThang?: number;
  /** Khoảng tự chọn cho KỲ ĐANG XEM. */
  tu?: string;
  den?: string;
  /** Khoảng tự chọn cho KỲ NỀN (dùng với `soSanh=TUY_CHON`). */
  nenTu?: string;
  nenDen?: string;
}


@Injectable()
export class ReportsService {
  private readonly logger = new Logger(ReportsService.name);
  private boVuAn?: BoTimKiem;
  private boVuViec?: BoTimKiem;
  private boDonThu?: BoTimKiem;

  // Tìm kiếm dạng thẻ của Hồ sơ trễ hạn — MỘT bộ cho mỗi khai, tạo LƯỜI (`this.prisma` chưa gán lúc
  // khởi tạo field); mỗi bộ nhớ riêng câu trả lời "bảng còn dòng chưa nạp cột bóng".
  private get timKiemVuAn(): BoTimKiem {
    return (this.boVuAn ??= new BoTimKiem(
      this.prisma,
      KHAI_TIM_KIEM_VU_AN,
      THAM_SO_CU_TRE_HAN,
    ));
  }

  private get timKiemVuViec(): BoTimKiem {
    return (this.boVuViec ??= new BoTimKiem(
      this.prisma,
      KHAI_TIM_KIEM_VU_VIEC,
      THAM_SO_CU_TRE_HAN,
    ));
  }

  private get timKiemDonThu(): BoTimKiem {
    return (this.boDonThu ??= new BoTimKiem(
      this.prisma,
      KHAI_TIM_KIEM_DON_THU,
      THAM_SO_CU_TRE_HAN,
    ));
  }

  constructor(private readonly prisma: PrismaService) {}

  /**
   * Đếm bốn chỉ tiêu trong một khoảng bất kỳ.
   *
   * Tách ra KHÔNG phải để bớt dòng, mà vì kỳ nền bắt buộc phải được đếm bằng ĐÚNG MỘT THƯỚC
   * với kỳ hiện tại: cùng điều kiện `deletedAt`, cùng cột thời gian, cùng tập trạng thái. Hai
   * bản sao của cùng một phép đếm là hai thước sẽ lệch nhau ở lần sửa thứ nhất — và lúc ấy
   * chênh lệch đo được sẽ một phần là do đổi thước, không ai biết là phần nào.
   */
  private async demTrongKhoang(tu: Date, den: Date) {
    const trongKy = { gte: tu, lte: den };
    const [donThu, vuViec, vuAn, daGiaiQuyet] = await Promise.all([
      this.prisma.petition.count({
        where: { deletedAt: null, [COT_NGAY_TIEP_NHAN.petition]: trongKy },
      }),
      this.prisma.incident.count({
        where: { deletedAt: null, [COT_NGAY_TIEP_NHAN.incident]: trongKy },
      }),
      this.prisma.case.count({
        where: { deletedAt: null, [COT_NGAY_TIEP_NHAN.case]: trongKy },
      }),
      // "Đã giải quyết" đếm theo MỐC GIẢI QUYẾT (`ngayGiaiQuyet`), không theo `updatedAt`.
      // `updatedAt` là lần chạm bản ghi gần nhất, nên mọi kỳ đã qua đều ra 0 — không phải vì
      // không giải quyết được vụ nào, mà vì không hồ sơ nào được động tới trong kỳ ấy.
      //
      // Hồ sơ đã ở trạng thái kết thúc từ TRƯỚC khi có cột này thì mốc rỗng, nên KHÔNG vào kỳ
      // nào. Chúng được đếm riêng ở `daGiaiQuyetChuaRoNgay` và hiện trên màn — bịa một ngày cho
      // chúng là bịa đúng con số mà cả đợt này đi sửa.
      Promise.all([
        this.prisma.case.count({ where: { deletedAt: null, ngayGiaiQuyet: trongKy } }),
        this.prisma.incident.count({ where: { deletedAt: null, ngayGiaiQuyet: trongKy } }),
        this.prisma.petition.count({ where: { deletedAt: null, ngayGiaiQuyet: trongKy } }),
      ]).then(([c, i, p]) => c + i + p),
    ]);
    return { donThu, vuViec, vuAn, daGiaiQuyet };
  }

  /**
   * Hồ sơ KHÔNG lọt vào bất kỳ kỳ báo cáo nào, vì ngày tiếp nhận trống hoặc nằm ngoài
   * 1900–2100.
   *
   * Có hàm này vì đổi từ `createdAt` sang ngày nghiệp vụ làm một số hồ sơ biến mất khỏi mọi
   * kỳ — đo được 42 vụ án thiếu ngày và 2 hồ sơ mang năm rác. Con số ấy nhỏ, nhưng một hồ sơ
   * không lọt vào báo cáo nào là một hồ sơ VÔ HÌNH, và điều đó phải hiện trên màn chứ không
   * nằm trong đầu người viết mã.
   */
  /**
   * Hồ sơ ĐANG Ở trạng thái kết thúc mà chưa có mốc giải quyết.
   *
   * Toàn bộ số này là di sản: cột `ngayGiaiQuyet` mới có từ 30/08/2026, còn hồ sơ kết thúc
   * trước đó không có mốc nào để đặt. Con số sẽ tự teo dần khi cán bộ xử lý hồ sơ mới, và nó
   * PHẢI hiện trên màn cho tới lúc ấy — nếu không thì "đã giải quyết: 0" đọc như một sự thật.
   */
  private async demDaGiaiQuyetChuaRoNgay() {
    const [vuAn, vuViec, donThu] = await Promise.all([
      this.prisma.case.count({
        where: { deletedAt: null, ngayGiaiQuyet: null, status: { in: TRANG_THAI_KET_THUC.case } },
      }),
      this.prisma.incident.count({
        where: {
          deletedAt: null,
          ngayGiaiQuyet: null,
          status: { in: TRANG_THAI_KET_THUC.incident },
        },
      }),
      this.prisma.petition.count({
        where: {
          deletedAt: null,
          ngayGiaiQuyet: null,
          status: { in: TRANG_THAI_KET_THUC.petition },
        },
      }),
    ]);
    return { donThu, vuViec, vuAn, tong: donThu + vuViec + vuAn };
  }

  /**
   * Năm sớm nhất và muộn nhất CÓ dữ liệu, để ô chọn năm sinh từ thực tế.
   *
   * Ô ấy viết cứng 2024–2026 trong khi hồ sơ có từ 2006 — hơn mười lăm năm dữ liệu không có
   * đường bấm tới, và không gì trên màn nói ra điều đó. Người dùng chỉ thấy một danh sách ba
   * năm và tin rằng đó là tất cả.
   */
  private async namCoDuLieu() {
    const [p, i, c] = await Promise.all([
      this.prisma.petition.aggregate({
        where: { deletedAt: null, receivedDate: { gte: MOC_NAM_HOP_LE.dau, lte: MOC_NAM_HOP_LE.cuoi } },
        _min: { receivedDate: true },
        _max: { receivedDate: true },
      }),
      this.prisma.incident.aggregate({
        where: { deletedAt: null, ngayDeXuat: { gte: MOC_NAM_HOP_LE.dau, lte: MOC_NAM_HOP_LE.cuoi } },
        _min: { ngayDeXuat: true },
        _max: { ngayDeXuat: true },
      }),
      this.prisma.case.aggregate({
        where: { deletedAt: null, receiveDate: { gte: MOC_NAM_HOP_LE.dau, lte: MOC_NAM_HOP_LE.cuoi } },
        _min: { receiveDate: true },
        _max: { receiveDate: true },
      }),
    ]);
    const nams = [
      p._min.receivedDate, p._max.receivedDate,
      i._min.ngayDeXuat, i._max.ngayDeXuat,
      c._min.receiveDate, c._max.receiveDate,
    ].filter((d): d is Date => d instanceof Date).map((d) => d.getFullYear());
    const nayNam = new Date().getFullYear();
    if (!nams.length) return { tu: nayNam, den: nayNam };
    // KHÔNG cho chọn năm TƯƠNG LAI. Đo trên máy thật: có hồ sơ mang ngày tới tận 2036 — ngày gõ
    // hỏng ở hệ cũ. Để chúng kéo dải năm ra tới 2036 là bày trước mắt cán bộ mười năm không có
    // gì, và một danh sách năm trông như có dữ liệu là một lời hứa suông.
    //
    // Chúng vẫn với tới được bằng khoảng tự chọn — không mất, chỉ không bày ra.
    return { tu: Math.min(...nams), den: nayNam };
  }

  private async demKhongCoNgayTiepNhan() {
    // Viết TƯỜNG MINH ba truy vấn thay vì dựng điều kiện bằng khoá động: khoá động buộc phải
    // ép kiểu, và `as never` ở bản trước đã bịt đúng lời cảnh báo cần nghe — `receivedDate`
    // của đơn thư KHÔNG cho phép rỗng, nên hỏi `{ receivedDate: null }` là điều kiện sai kiểu
    // mà Prisma có thể từ chối lúc chạy, làm hỏng cả endpoint báo cáo.
    const [donThu, vuViec, vuAn] = await Promise.all([
      // Đơn thư: cột bắt buộc, chỉ có thể nằm ngoài khoảng chứ không thể rỗng.
      this.prisma.petition.count({
        where: {
          deletedAt: null,
          OR: [
            { receivedDate: { lt: MOC_NAM_HOP_LE.dau } },
            { receivedDate: { gt: MOC_NAM_HOP_LE.cuoi } },
          ],
        },
      }),
      this.prisma.incident.count({
        where: {
          deletedAt: null,
          OR: [
            { ngayDeXuat: null },
            { ngayDeXuat: { lt: MOC_NAM_HOP_LE.dau } },
            { ngayDeXuat: { gt: MOC_NAM_HOP_LE.cuoi } },
          ],
        },
      }),
      this.prisma.case.count({
        where: {
          deletedAt: null,
          OR: [
            { receiveDate: null },
            { receiveDate: { lt: MOC_NAM_HOP_LE.dau } },
            { receiveDate: { gt: MOC_NAM_HOP_LE.cuoi } },
          ],
        },
      }),
    ]);
    return { donThu, vuViec, vuAn, tong: donThu + vuViec + vuAn };
  }

  // ─────────────────────────────────────────────
  // GET /api/v1/reports/monthly?year=&month=
  // ─────────────────────────────────────────────
  async getMonthly(
    year: number,
    month?: number,
    kieuSoSanh: KieuSoSanh = KIEU_SO_SANH_MAC_DINH,
    tuyChon?: TuyChonKy,
  ) {
    const kyChon = chonKy(year, month, tuyChon, (n, m) => kyThang(n, m));
    const months = thangTrongKy(kyChon);

    const data = await Promise.all(
      // Ô biểu đồ đếm phần GIAO với kỳ đang chọn, không đếm trọn tháng.
      //
      // Với khoảng 05/03–20/05, ô tháng 3 đếm trọn tháng 3 thì tổng các ô KHÁC dòng tổng — hai
      // con số trên cùng một tệp không cộng ra nhau, và người đọc không có cách nào biết bên
      // nào đúng.
      months.map(async (m) => ({
        month: `T${m.so}/${m.nam}`,
        ...(await this.demTrongKhoang(m.tu, m.den)),
      })),
    );


    const ky = kyChon;
    // Tổng đếm THẲNG trên kỳ đang chọn, không cộng dồn các ô của biểu đồ.
    //
    // Bản đầu cộng 12 ô tháng lại — nên chọn "lũy kế 8 tháng" hay một khoảng tự chọn thì nhãn
    // và huy hiệu nói đúng kỳ ấy, còn bốn thẻ số vẫn là CẢ NĂM. Hai câu về hai kỳ khác nhau
    // đứng cạnh nhau trên một màn, và không có gì trên màn lộ ra điều đó.
    const totals = await this.demTrongKhoang(ky.tu, ky.den);
    const soSanh = await dungSoSanh(
      ky,
      // `tongTiepNhan` không nằm trong `totals` để không đổi hình dạng phản hồi cũ, nhưng vẫn
      // phải được so: màn Báo cáo quý có một thẻ đúng bằng tổng ba loại hồ sơ, và thẻ ấy cần
      // huy hiệu như ba thẻ kia.
      async (tu, den) => {
        const d = await this.demTrongKhoang(tu, den);
        return { ...d, tongTiepNhan: d.donThu + d.vuViec + d.vuAn };
      },
      { ...totals, tongTiepNhan: totals.donThu + totals.vuViec + totals.vuAn },
      kieuSoSanh,
      new Date(),
      tuyChon?.nenTu && tuyChon?.nenDen
        ? kyTuyChon(new Date(tuyChon.nenTu), new Date(tuyChon.nenDen))
        : undefined,
    );

    const [khongCoNgay, daGiaiQuyetChuaRoNgay, namCoDuLieu] = await Promise.all([
      this.demKhongCoNgayTiepNhan(),
      this.demDaGiaiQuyetChuaRoNgay(),
      this.namCoDuLieu(),
    ]);
    return {
      success: true,
      data,
      totals,
      year,
      month,
      kyNhan: ky.nhan,
      soSanh,
      khongCoNgay,
      daGiaiQuyetChuaRoNgay,
      namCoDuLieu,
    };
  }

  // ─────────────────────────────────────────────
  // GET /api/v1/reports/quarterly?year=&quarter=
  // ─────────────────────────────────────────────
  async getQuarterly(
    year: number,
    quarter?: number,
    kieuSoSanh: KieuSoSanh = KIEU_SO_SANH_MAC_DINH,
    tuyChon?: TuyChonKy,
  ) {
    const kyChon = chonKy(year, quarter, tuyChon, (n, q) => kyQuy(n, q));
    const quarters = quyTrongKy(kyChon);

    const data = await Promise.all(
      // Xem chú thích cùng nội dung ở `getMonthly`.
      quarters.map(async (q) => ({
        quarter: `Q${q.so}/${q.nam}`,
        ...(await this.demTrongKhoang(q.tu, q.den)),
      })),
    );


    const ky = kyChon;
    // Xem chú thích cùng nội dung ở `getMonthly`.
    const totals = await this.demTrongKhoang(ky.tu, ky.den);
    const soSanh = await dungSoSanh(
      ky,
      // `tongTiepNhan` không nằm trong `totals` để không đổi hình dạng phản hồi cũ, nhưng vẫn
      // phải được so: màn Báo cáo quý có một thẻ đúng bằng tổng ba loại hồ sơ, và thẻ ấy cần
      // huy hiệu như ba thẻ kia.
      async (tu, den) => {
        const d = await this.demTrongKhoang(tu, den);
        return { ...d, tongTiepNhan: d.donThu + d.vuViec + d.vuAn };
      },
      { ...totals, tongTiepNhan: totals.donThu + totals.vuViec + totals.vuAn },
      kieuSoSanh,
      new Date(),
      tuyChon?.nenTu && tuyChon?.nenDen
        ? kyTuyChon(new Date(tuyChon.nenTu), new Date(tuyChon.nenDen))
        : undefined,
    );

    const [khongCoNgay, daGiaiQuyetChuaRoNgay, namCoDuLieu] = await Promise.all([
      this.demKhongCoNgayTiepNhan(),
      this.demDaGiaiQuyetChuaRoNgay(),
      this.namCoDuLieu(),
    ]);
    return {
      success: true,
      data,
      totals,
      year,
      quarter,
      kyNhan: ky.nhan,
      soSanh,
      khongCoNgay,
      daGiaiQuyetChuaRoNgay,
      namCoDuLieu,
    };
  }

  // ─────────────────────────────────────────────
  // GET /api/v1/reports/district-stats?fromDate=&toDate=&district=
  // Lưu ý: district = tên phường/xã (cải cách hành chính 2025 — không còn cấp quận/huyện)
  // ─────────────────────────────────────────────
  async getDistrictStats(fromDate?: string, toDate?: string, district?: string) {
    const from = fromDate ? new Date(fromDate) : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
    const to = toDate ? new Date(toDate + 'T23:59:59.999Z') : new Date();

    // Ward filter: Case stores province/ward in metadata JSON field
    // Prisma JSON path query: metadata->>'ward' = district
    const caseWardFilter = district
      ? { metadata: { path: ['ward'], equals: district } }
      : {};

    // Daily breakdown for date range
    const dayCount = Math.ceil((to.getTime() - from.getTime()) / (1000 * 60 * 60 * 24));
    const limitDays = Math.min(dayCount, 31); // max 31 days for chart

    const dailyData = await Promise.all(
      Array.from({ length: limitDays }, async (_, i) => {
        const dayStart = new Date(from);
        dayStart.setDate(dayStart.getDate() + i);
        dayStart.setHours(0, 0, 0, 0);
        const dayEnd = new Date(dayStart);
        dayEnd.setHours(23, 59, 59, 999);

        const [petitions, incidents, cases] = await Promise.all([
          this.prisma.petition.count({
            where: { deletedAt: null, createdAt: { gte: dayStart, lte: dayEnd } },
            // Note: Petition has no direct ward field — not filtered by ward yet
          }),
          this.prisma.incident.count({
            where: { deletedAt: null, createdAt: { gte: dayStart, lte: dayEnd } },
            // Note: Incident has no direct ward field — not filtered by ward yet
          }),
          this.prisma.case.count({
            where: {
              deletedAt: null,
              createdAt: { gte: dayStart, lte: dayEnd },
              ...caseWardFilter,
            },
          }),
        ]);

        return {
          date: dayStart.toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit' }),
          count: petitions + incidents + cases,
          details: { petitions, incidents, cases },
        };
      }),
    );

    // Incident status breakdown
    const incidentStatusCounts = await this.prisma.incident.groupBy({
      by: ['status'],
      where: {
        deletedAt: null,
        createdAt: { gte: from, lte: to },
        // Incident ward filter not yet implemented (no direct ward field)
      },
      _count: { id: true },
    });

    const INCIDENT_STATUS_LABELS: Record<string, string> = {
      TIEP_NHAN: 'Tiếp nhận',
      DANG_XAC_MINH: 'Đang xác minh',
      DA_GIAI_QUYET: 'Đã giải quyết',
      TAM_DINH_CHI: 'Tạm đình chỉ',
      QUA_HAN: 'Quá hạn',
      DA_CHUYEN_VU_AN: 'Đã chuyển vụ án',
    };

    // Case status breakdown — apply ward filter
    const caseStatusCounts = await this.prisma.case.groupBy({
      by: ['status'],
      where: {
        deletedAt: null,
        createdAt: { gte: from, lte: to },
        ...caseWardFilter,
      },
      _count: { id: true },
    });

    const CASE_STATUS_LABELS: Record<string, string> = {
      TIEP_NHAN: 'Tiếp nhận',
      DANG_XAC_MINH: 'Đang xác minh',
      DANG_DIEU_TRA: 'Đang điều tra',
      DA_KET_LUAN: 'Đã kết luận',
      DA_LUU_TRU: 'Đã lưu trữ',
      DINH_CHI: 'Đình chỉ',
      TAM_DINH_CHI: 'Tạm đình chỉ',
      DANG_TRUY_TO: 'Đang truy tố',
      DANG_XET_XU: 'Đang xét xử',
      DA_XAC_MINH: 'Đã xác minh',
    };

    const COLORS = ['#1B2B4E', '#D4AF37', '#64748B', '#10B981', '#F59E0B', '#EF4444'];

    return {
      success: true,
      data: {
        daily: dailyData,
        incidentStatus: incidentStatusCounts.map((item, idx) => ({
          name: INCIDENT_STATUS_LABELS[item.status] ?? item.status,
          value: item._count.id,
          color: COLORS[idx % COLORS.length],
        })),
        caseStatus: caseStatusCounts.map((item, idx) => ({
          name: CASE_STATUS_LABELS[item.status] ?? item.status,
          value: item._count.id,
          color: COLORS[idx % COLORS.length],
        })),
      },
      filters: { fromDate: from.toISOString(), toDate: to.toISOString(), district },
    };
  }

  // ─────────────────────────────────────────────
  // GET /api/v1/reports/overdue
  // ─────────────────────────────────────────────
  async getOverdue(
    search?: string,
    recordType?: string,
    priority?: string,
    minDaysOverdue?: number,
    tk?: string[],
  ) {
    const now = new Date();

    // Thẻ tìm kiếm: MỘT ô cho ba loại hồ sơ → chỉ nhận "*" và khoá CHUNG ba khai (cùng nghĩa trên cả
    // ba bảng); khoá khác 400 trước khi hỏi CSDL. Mỗi bảng dựng điều kiện bằng BoTimKiem của CHÍNH
    // khai ấy (cột bóng riêng). Trước đây ba khối OR chép tay, `contains` thường, vụ việc còn so
    // `unitId` (một ID) như chữ.
    kiemTheChung(tk, KHAI_HO_SO_TRE_HAN);
    // So chữ thường: client gửi mã kiểu enum (`CASE`) thì mọi nhánh bị bỏ qua → danh sách rỗng mà
    // trông như "không có hồ sơ trễ hạn".
    const loai = recordType?.trim().toLowerCase();
    const mucUuTien = priority?.trim().toLowerCase();
    const thamSoTim = { search, tk };
    const [timVuAn, timVuViec, timDonThu] = await Promise.all([
      this.timKiemVuAn.dieuKien(thamSoTim),
      this.timKiemVuViec.dieuKien(thamSoTim),
      this.timKiemDonThu.dieuKien(thamSoTim),
    ]);

    const overdueCases =
      loai && loai !== 'case'
        ? []
        : await this.prisma.case.findMany({
            where: {
              deletedAt: null,
              deadline: { lt: now },
              status: {
                notIn: [
                  CaseStatus.DA_KET_LUAN,
                  CaseStatus.DA_LUU_TRU,
                  CaseStatus.DINH_CHI,
                ],
              },
              AND: timVuAn,
            },
            select: {
              id: true,
              caseCode: true,
              name: true,
              deadline: true,
              createdAt: true,
              unit: true,
              status: true,
              investigator: {
                select: { id: true, firstName: true, lastName: true },
              },
            },
            orderBy: { deadline: 'asc' },
          });

    const overdueIncidents =
      loai && loai !== 'incident'
        ? []
        : await this.prisma.incident.findMany({
            where: {
              deletedAt: null,
              deadline: { lt: now },
              status: {
                notIn: [
                  IncidentStatus.DA_GIAI_QUYET,
                  IncidentStatus.DA_CHUYEN_VU_AN,
                ],
              },
              AND: timVuViec,
            },
            select: {
              id: true,
              code: true,
              name: true,
              deadline: true,
              createdAt: true,
              unitId: true,
              status: true,
              investigator: {
                select: { id: true, firstName: true, lastName: true },
              },
            },
            orderBy: { deadline: 'asc' },
          });

    const overduePetitions =
      loai && loai !== 'petition'
        ? []
        : await this.prisma.petition.findMany({
            where: {
              deletedAt: null,
              deadline: { lt: now },
              status: {
                notIn: [
                  PetitionStatus.DA_GIAI_QUYET,
                  PetitionStatus.DA_CHUYEN_VU_AN,
                  PetitionStatus.DA_CHUYEN_VU_VIEC,
                ],
              },
              AND: timDonThu,
            },
            select: {
              id: true,
              stt: true,
              summary: true,
              deadline: true,
              receivedDate: true,
              unit: true,
              status: true,
              priority: true,
              assignedTo: {
                select: { id: true, firstName: true, lastName: true },
              },
            },
            orderBy: { deadline: 'asc' },
          });

    const toOverdueRecord = (item: any, type: string) => {
      const deadline = new Date(item.deadline);
      const daysOverdue = Math.floor((now.getTime() - deadline.getTime()) / (1000 * 60 * 60 * 24));
      const computedPriority = daysOverdue > 30 ? 'critical' : daysOverdue > 14 ? 'high' : 'medium';

      return {
        id: item.id,
        recordType: type,
        recordNumber: soHoSo(item as NguonSoHoSo),
        title: item.name ?? item.summary ?? `Đơn thư ${item.stt}`,
        assignedTo: item.investigator
          ? `${item.investigator.firstName ?? ''} ${item.investigator.lastName ?? ''}`.trim()
          : item.assignedTo
          ? `${item.assignedTo.firstName ?? ''} ${item.assignedTo.lastName ?? ''}`.trim()
          : 'Chưa phân công',
        unit: item.unit ?? item.unitId ?? '',
        dueDate: deadline.toISOString(),
        receivedDate: (item.createdAt ?? item.receivedDate ?? new Date()).toISOString(),
        daysOverdue,
        status: item.status,
        priority: item.priority ?? computedPriority,
      };
    };

    let records = [
      ...overdueCases.map((c) => toOverdueRecord(c, 'case')),
      ...overdueIncidents.map((i) => toOverdueRecord(i, 'incident')),
      ...overduePetitions.map((p) => toOverdueRecord(p, 'petition')),
    ];

    // Filter by minDaysOverdue
    if (minDaysOverdue && minDaysOverdue > 0) {
      records = records.filter((r) => r.daysOverdue >= minDaysOverdue);
    }

    // Mức ưu tiên là giá trị SUY RA khi dựng bản ghi (theo số ngày trễ) nên lọc ở đây, không lọc được
    // trong câu hỏi CSDL. Trước đây tham số này nhận rồi bỏ qua: gọi API với `priority=critical` vẫn
    // trả cả medium/high (màn lọc lại phía trình duyệt nên chỉ ai gọi API mới thấy sai).
    if (mucUuTien) {
      records = records.filter((r) => r.priority === mucUuTien);
    }

    // Sort by daysOverdue descending
    records.sort((a, b) => b.daysOverdue - a.daysOverdue);

    return {
      success: true,
      data: records,
      total: records.length,
    };
  }

  // ─────────────────────────────────────────────
  // GET /api/v1/reports/stat48?fromDate=&toDate=&unit=
  // ─────────────────────────────────────────────
  async getStat48(fromDate: string, toDate: string, unit?: string) {
    const from = new Date(fromDate);
    const to = new Date(toDate + 'T23:59:59.999Z');

    const cases = await this.prisma.case.findMany({
      where: {
        createdAt: { gte: from, lte: to },
        deletedAt: null,
        ...(unit ? { unit } : {}),
      },
      select: { metadata: true },
    });

    if (cases.length > 2000) {
      this.logger.warn(
        `getStat48: ${cases.length} cases — consider narrowing date range`,
      );
    }

    const totalCases = cases.length;
    const nullCount = cases.filter(
      (c) => !(c.metadata as Record<string, unknown> | null)?.['stat48'],
    ).length;
    const nullRatePct =
      totalCases > 0 ? Math.round((nullCount / totalCases) * 100) : 0;

    const groups = STAT_GROUPS.map((group) => ({
      name: group.name,
      fields: group.fields.map((field) => {
        const values = cases
          .map((c) => {
            const meta = c.metadata as Record<string, unknown> | null;
            const stat48 = meta?.['stat48'] as Record<string, unknown> | undefined;
            return stat48?.[field];
          })
          .filter((v) => v != null && v !== '');

        const dataCount = values.length;

        if (NUMERIC_FIELDS.has(field)) {
          const total = values.reduce(
            (a: number, b) => a + Number(b ?? 0),
            0,
          ) as number;
          return {
            field,
            type: 'numeric' as const,
            total,
            dataCount,
            nullCount: totalCases - dataCount,
          };
        } else {
          const dist: Record<string, number> = {};
          values.forEach((v) => {
            const key = String(v);
            dist[key] = (dist[key] ?? 0) + 1;
          });
          return {
            field,
            type: 'categorical' as const,
            distribution: dist,
            dataCount,
            nullCount: totalCases - dataCount,
          };
        }
      }),
    }));

    return {
      success: true,
      totalCases,
      nullCount,
      nullRatePct,
      isDraft: nullRatePct > 50,
      fromDate,
      toDate,
      unit,
      groups,
    };
  }
}

