import { dungSoSanh } from './dung-so-sanh';
import { kyThang, kyNam, kyLuyKe, kyTuyChon } from './ky-bao-cao';

/** Bộ đếm giả: trả số cố định, và ghi lại nó được hỏi khoảng nào. */
function boDemGia(tra: Record<string, number>) {
  const daHoi: Array<[Date, Date]> = [];
  const dem = async (tu: Date, den: Date) => {
    daHoi.push([tu, den]);
    return tra;
  };
  return { dem, daHoi };
}

const NGAY = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

describe('dungSoSanh — chọn đúng kỳ nền', () => {
  it('mặc định hỏi CÙNG KỲ NĂM TRƯỚC, không phải tháng trước', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 100 });
    // Mốc sau khi tháng 8/2026 đã đóng → kỳ trọn.
    await dungSoSanh(kyThang(2026, 8), dem, { donThu: 120 }, undefined, new Date(2026, 8, 15));
    expect(daHoi).toHaveLength(1);
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2025-08-01', '2025-08-31']);
  });

  it('chọn KY_LIEN_TRUOC thì hỏi tháng 7 cùng năm', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 100 });
    await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 120 },
      'KY_LIEN_TRUOC',
      new Date(2026, 8, 15),
    );
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2026-07-01', '2026-07-31']);
  });

  it('chọn KHONG thì KHÔNG hỏi máy chủ lần nào, và mọi kết quả đều rỗng chứ không phải 0', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 100 });
    const kq = await dungSoSanh(kyThang(2026, 8), dem, { donThu: 120 }, 'KHONG');
    expect(daHoi).toHaveLength(0);
    expect(kq.nen).toBeNull();
    expect(kq.chiTieu.donThu.tyLe).toBeNull();
    expect(kq.chiTieu.donThu.chenhLech).toBeNull();
    expect(kq.chiTieu.donThu.hienTai).toBe(120);
  });
});

describe('dungSoSanh — kỳ chưa trọn', () => {
  it('đang ngày 10/8 thì nền BỊ CẮT còn 10 ngày đầu tháng 8 năm trước', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 40 });
    const kq = await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 45 },
      undefined,
      new Date(2026, 7, 10, 14),
    );
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2025-08-01', '2025-08-10']);
    expect(kq.kyChuaTron).toBe(true);
    expect(kq.soNgayDaTroi).toBe(10);
    expect(kq.nen!.nhan).toBe('tháng 8/2025 (10 ngày đầu)');
  });

  /**
   * Đây là ca chứng minh phép cắt có giá trị thật, không phải trang trí: KHÔNG cắt thì tháng
   * nào cũng "giảm" chỉ vì kỳ này mới chạy được một phần ba.
   */
  it('không cắt thì kết luận ngược dấu — cắt rồi mới đọc đúng', async () => {
    // Tháng 8 năm ngoái: 10 ngày đầu có 40, cả tháng có 130.
    const dem = async (tu: Date, den: Date) => ({ donThu: NGAY(den) === '2025-08-10' ? 40 : 130 });
    const catDung = await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 45 },
      undefined,
      new Date(2026, 7, 10, 14),
    );
    // Cắt đúng: 45 so với 40 → TĂNG.
    expect(catDung.chiTieu.donThu.chieu).toBe('TANG');
    // Nếu đem so với cả tháng (130) thì ra GIẢM 65% — kết luận sai, và sai theo hướng nghe êm tai.
    const neuKhongCat = 45 - 130;
    expect(neuKhongCat).toBeLessThan(0);
  });

  it('kỳ đã đóng thì nền không bị cắt', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 100 });
    const kq = await dungSoSanh(
      kyThang(2026, 7),
      dem,
      { donThu: 120 },
      undefined,
      new Date(2026, 7, 10),
    );
    expect(kq.kyChuaTron).toBe(false);
    expect(kq.soNgayDaTroi).toBeNull();
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2025-07-01', '2025-07-31']);
    expect(kq.nen!.nhan).toBe('tháng 7/2025');
  });
});

describe('dungSoSanh — chiều tốt/xấu đi theo chỉ tiêu', () => {
  it('cùng một dấu trừ, hai nghĩa trái nhau', async () => {
    const dem = async () => ({ quaHan: 50, daGiaiQuyet: 50 });
    const kq = await dungSoSanh(
      kyNam(2026),
      dem,
      { quaHan: 30, daGiaiQuyet: 30 },
      undefined,
      new Date(2027, 0, 5),
    );
    expect(kq.chiTieu.quaHan.tot).toBe(true); // quá hạn giảm → tốt
    expect(kq.chiTieu.daGiaiQuyet.tot).toBe(false); // đã giải quyết giảm → xấu
  });

  it('chỉ tiêu trung tính không bị gán tốt/xấu', async () => {
    const dem = async () => ({ donThu: 50 });
    const kq = await dungSoSanh(
      kyNam(2026),
      dem,
      { donThu: 90 },
      undefined,
      new Date(2027, 0, 5),
    );
    expect(kq.chiTieu.donThu.chieu).toBe('TANG');
    expect(kq.chiTieu.donThu.tot).toBeNull();
  });
});

describe('dungSoSanh — chỉ tiêu thiếu ở kỳ nền', () => {
  it('nền không có khoá ấy thì coi là 0, không đổ vỡ', async () => {
    const dem = async () => ({});
    const kq = await dungSoSanh(kyNam(2026), dem, { donThu: 7 }, undefined, new Date(2027, 0, 5));
    expect(kq.chiTieu.donThu.nen).toBe(0);
    expect(kq.chiTieu.donThu.lyDoKhongCoTyLe).toBe('NEN_BANG_KHONG');
  });
});

describe('dungSoSanh — kỳ nằm ở TƯƠNG LAI', () => {
  /**
   * Codex bắt. API cho phép hỏi tháng 12 khi mới tháng 8. Kỳ ấy chưa trôi ngày nào, nhưng phép
   * cắt cũ đặt `den = tu` — và bộ lọc Prisma dùng `gte`/`lte` nên vẫn ĐẾM ĐƯỢC bản ghi ở đúng
   * thời khắc 00:00:00.000 ngày đầu kỳ nền. Kết quả: một kỳ chưa bắt đầu vẫn có nền khác 0 và
   * vẫn ra chênh lệch — một con số hoàn toàn vô nghĩa, trình bày y như số thật.
   *
   * Câu trả lời đúng không phải "cắt cho nhỏ lại" mà là "KHÔNG CÓ NỀN": chưa có ngày nào trôi
   * thì không có gì để so.
   */
  it('kỳ chưa bắt đầu thì KHÔNG hỏi kỳ nền, và không đưa ra chênh lệch nào', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 999 });
    const kq = await dungSoSanh(
      kyThang(2026, 12),
      dem,
      { donThu: 0 },
      undefined,
      new Date(2026, 7, 15),
    );
    expect(daHoi).toHaveLength(0);
    expect(kq.nen).toBeNull();
    expect(kq.chiTieu.donThu.chenhLech).toBeNull();
    expect(kq.chiTieu.donThu.lyDoKhongCoTyLe).toBe('KHONG_CO_NEN');
  });

  it('ngày ĐẦU TIÊN của kỳ thì đã có nền — ranh giới không lệch một ngày', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 5 });
    const kq = await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 2 },
      undefined,
      new Date(2026, 7, 1, 0, 30),
    );
    expect(daHoi).toHaveLength(1);
    expect(kq.soNgayDaTroi).toBe(1);
    expect(kq.nen).not.toBeNull();
  });
});

describe('dungSoSanh — kỳ LŨY KẾ', () => {
  it('lũy kế 8 tháng so với LŨY KẾ 8 THÁNG năm trước, không phải cả năm trước', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 100 });
    const kq = await dungSoSanh(
      kyLuyKe(2026, 8),
      dem,
      { donThu: 120 },
      undefined,
      new Date(2026, 8, 15),
    );
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2025-01-01', '2025-08-31']);
    expect(kq.nen!.nhan).toBe('lũy kế 8 tháng đầu năm 2025');
    expect(kq.chiTieu.donThu.tyLe).toBe(20);
  });
});

describe('dungSoSanh — nền TUỲ CHỌN', () => {
  it('hỏi ĐÚNG khoảng người dùng chọn, không tự dịch kỳ', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 80 });
    const nen = kyTuyChon(new Date(2024, 0, 1), new Date(2024, 5, 30));
    const kq = await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 100 },
      'TUY_CHON',
      new Date(2026, 8, 15),
      nen,
    );
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2024-01-01', '2024-06-30']);
    expect(kq.nen!.nhan).toBe('01/01/2024 – 30/06/2024');
    expect(kq.chiTieu.donThu.tyLe).toBe(25);
  });

  /**
   * Nền tuỳ chọn KHÔNG bị cắt theo tiến độ. Người dùng đã tự chọn hai đầu; cắt tiếp là sửa lựa
   * chọn của họ mà không nói một lời.
   */
  it('kỳ đang chạy cũng KHÔNG cắt nền tuỳ chọn', async () => {
    const { dem, daHoi } = boDemGia({ donThu: 80 });
    const nen = kyTuyChon(new Date(2024, 0, 1), new Date(2024, 5, 30));
    const kq = await dungSoSanh(
      kyThang(2026, 8),
      dem,
      { donThu: 100 },
      'TUY_CHON',
      new Date(2026, 7, 10),
      nen,
    );
    expect([NGAY(daHoi[0][0]), NGAY(daHoi[0][1])]).toEqual(['2024-01-01', '2024-06-30']);
    expect(kq.kyChuaTron).toBe(true);
  });

  it('chọn TUY_CHON mà quên khoảng nền thì NÉM LỖI, không lặng lẽ rơi về mặc định', async () => {
    const { dem } = boDemGia({ donThu: 80 });
    await expect(
      dungSoSanh(kyThang(2026, 8), dem, { donThu: 100 }, 'TUY_CHON', new Date(2026, 8, 15)),
    ).rejects.toThrow();
  });
});

import { Ky, cungKyNamTruoc, kyLienTruoc, kyChuaTron, soNgayDaTroi, catTheoTienDo } from './ky-bao-cao';
import { KetQuaSoSanh, soSanh } from './so-sanh';
import { chieuTotCua } from './chi-tieu';

/** Nền để so. Mặc định là cùng kỳ năm trước, theo quy ước báo cáo ngành. */
export type KieuSoSanh = 'CUNG_KY_NAM_TRUOC' | 'KY_LIEN_TRUOC' | 'TUY_CHON' | 'KHONG';

export const KIEU_SO_SANH_MAC_DINH: KieuSoSanh = 'CUNG_KY_NAM_TRUOC';

export interface MoTaKy {
  tu: string;
  den: string;
  nhan: string;
}

export interface KhoiSoSanh {
  kieu: KieuSoSanh;
  /** Kỳ đang xem. */
  ky: MoTaKy;
  /** Kỳ được lấy làm nền. `null` khi kiểu là KHONG. */
  nen: MoTaKy | null;
  /**
   * Kỳ hiện tại chưa đóng — số liệu còn chạy tiếp. Khi đó `nen` đã được CẮT cho khớp số ngày
   * đã trôi, và `nhan` của nó nói rõ điều đó.
   */
  kyChuaTron: boolean;
  /** Số ngày đã trôi của kỳ hiện tại, chỉ có nghĩa khi `kyChuaTron`. */
  soNgayDaTroi: number | null;
  chiTieu: Record<string, KetQuaSoSanh>;
}

export type BoDem = Record<string, number>;

/**
 * Dựng khối so sánh cho một kỳ.
 *
 * Nhận vào một hàm ĐẾM để tầng này không biết gì về Prisma — nhờ vậy ca kiểm chạy được mà
 * không cần cơ sở dữ liệu, và mọi màn báo cáo khác dùng lại được y nguyên.
 */
export async function dungSoSanh(
  ky: Ky,
  demTrongKhoang: (tu: Date, den: Date) => Promise<BoDem>,
  soLieuHienTai: BoDem,
  kieu: KieuSoSanh = KIEU_SO_SANH_MAC_DINH,
  moc: Date = new Date(),
  /** Chỉ dùng với `kieu = 'TUY_CHON'`: khoảng nền do người dùng chọn. */
  nenTuyChon?: Ky,
): Promise<KhoiSoSanh> {
  const khoa = Object.keys(soLieuHienTai);

  if (kieu === 'KHONG') {
    return {
      kieu,
      ky: moTa(ky),
      nen: null,
      kyChuaTron: kyChuaTron(ky, moc),
      soNgayDaTroi: null,
      chiTieu: Object.fromEntries(
        khoa.map((k) => [k, soSanh(soLieuHienTai[k], null, chieuTotCua(k))]),
      ),
    };
  }

  const chuaTron = kyChuaTron(ky, moc);
  const daTroi = chuaTron ? soNgayDaTroi(ky, moc) : null;

  // Kỳ nằm ở TƯƠNG LAI — chưa trôi ngày nào. Không có gì để so, và nói "không có nền" mới đúng.
  // Cắt kỳ nền còn 0 ngày là sai theo hai nghĩa: bộ lọc `gte`/`lte` vẫn đếm được bản ghi ở đúng
  // thời khắc đầu kỳ, và một chênh lệch dựng trên đó trông y hệt một con số thật.
  if (chuaTron && daTroi === 0) {
    return {
      kieu,
      ky: moTa(ky),
      nen: null,
      kyChuaTron: true,
      soNgayDaTroi: 0,
      chiTieu: Object.fromEntries(
        khoa.map((k) => [k, soSanh(soLieuHienTai[k], null, chieuTotCua(k))]),
      ),
    };
  }

  // Nền tuỳ chọn KHÔNG bị cắt theo tiến độ: người dùng đã tự chọn hai đầu, cắt tiếp là sửa
  // lựa chọn của họ mà không nói. Với nền suy ra (cùng kỳ / kỳ liền trước) thì vẫn cắt.
  if (kieu === 'TUY_CHON') {
    if (!nenTuyChon) throw new Error('Kiểu so sánh TUY_CHON cần khoảng nền.');
    const soLieuNen = await demTrongKhoang(nenTuyChon.tu, nenTuyChon.den);
    return {
      kieu,
      ky: moTa(ky),
      nen: moTa(nenTuyChon),
      kyChuaTron: chuaTron,
      soNgayDaTroi: daTroi,
      chiTieu: Object.fromEntries(
        khoa.map((k) => [k, soSanh(soLieuHienTai[k], soLieuNen[k] ?? 0, chieuTotCua(k))]),
      ),
    };
  }

  const nenDay = kieu === 'KY_LIEN_TRUOC' ? kyLienTruoc(ky) : cungKyNamTruoc(ky);
  // Kỳ chưa đóng thì cắt nền cho khớp tiến độ — nếu không, mọi chỉ tiêu đều "giảm" chỉ vì kỳ
  // này mới chạy được vài ngày.
  const nen = chuaTron ? catTheoTienDo(nenDay, daTroi!) : nenDay;

  const soLieuNen = await demTrongKhoang(nen.tu, nen.den);

  return {
    kieu,
    ky: moTa(ky),
    nen: moTa(nen),
    kyChuaTron: chuaTron,
    soNgayDaTroi: daTroi,
    chiTieu: Object.fromEntries(
      khoa.map((k) => [k, soSanh(soLieuHienTai[k], soLieuNen[k] ?? 0, chieuTotCua(k))]),
    ),
  };
}

function moTa(k: Ky): MoTaKy {
  return { tu: k.tu.toISOString(), den: k.den.toISOString(), nhan: k.nhan };
}

