import {
  kyThang,
  kyQuy,
  kyNam,
  cungKyNamTruoc,
  kyLienTruoc,
  soNgayDaTroi,
  kyChuaTron,
  catTheoTienDo,
  kyLuyKe,
  kyTuyChon,
} from './ky-bao-cao';

/** Ngày cuối cùng của kỳ, đọc ra dạng dễ đối chiếu bằng mắt. */
function moc(k: { tu: Date; den: Date }): [string, string] {
  const f = (d: Date) =>
    `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
  return [f(k.tu), f(k.den)];
}

describe('Dựng kỳ — độ dài tháng tự đúng', () => {
  it('tháng 31 ngày', () => expect(moc(kyThang(2026, 1))).toEqual(['2026-01-01', '2026-01-31']));
  it('tháng 30 ngày', () => expect(moc(kyThang(2026, 4))).toEqual(['2026-04-01', '2026-04-30']));
  it('tháng 2 năm thường có 28 ngày', () =>
    expect(moc(kyThang(2027, 2))).toEqual(['2027-02-01', '2027-02-28']));
  it('tháng 2 năm nhuận có 29 ngày', () =>
    expect(moc(kyThang(2028, 2))).toEqual(['2028-02-01', '2028-02-29']));
  it('tháng 12 không tràn sang năm sau', () =>
    expect(moc(kyThang(2026, 12))).toEqual(['2026-12-01', '2026-12-31']));

  it('kỳ ôm trọn tới 23:59:59.999 — hồ sơ nhập lúc 22h tối ngày cuối vẫn thuộc kỳ', () => {
    const k = kyThang(2026, 1);
    expect(k.den.getHours()).toBe(23);
    expect(k.den.getMinutes()).toBe(59);
    expect(new Date(2026, 0, 31, 22, 0).getTime()).toBeLessThanOrEqual(k.den.getTime());
  });

  it('quý gồm đúng ba tháng', () => {
    expect(moc(kyQuy(2026, 1))).toEqual(['2026-01-01', '2026-03-31']);
    expect(moc(kyQuy(2026, 4))).toEqual(['2026-10-01', '2026-12-31']);
  });

  it('năm', () => expect(moc(kyNam(2026))).toEqual(['2026-01-01', '2026-12-31']));

  it('tháng và quý ngoài dải thì ném lỗi, không lặng lẽ trả kỳ sai', () => {
    expect(() => kyThang(2026, 0)).toThrow();
    expect(() => kyThang(2026, 13)).toThrow();
    expect(() => kyQuy(2026, 5)).toThrow();
  });
});

describe('Cùng kỳ năm trước', () => {
  it('tháng 2 NHUẬN lùi về tháng 2 THƯỜNG — 28 ngày, không trượt sang 1/3', () => {
    expect(moc(cungKyNamTruoc(kyThang(2028, 2)))).toEqual(['2027-02-01', '2027-02-28']);
  });

  it('giữ nguyên loại và số kỳ', () => {
    const k = cungKyNamTruoc(kyQuy(2026, 3));
    expect(k.loai).toBe('QUY');
    expect(k.so).toBe(3);
    expect(moc(k)).toEqual(['2025-07-01', '2025-09-30']);
  });

  it('nhãn nói đúng kỳ nào, để câu "so với …" không mơ hồ', () => {
    expect(cungKyNamTruoc(kyThang(2026, 8)).nhan).toBe('tháng 8/2025');
    expect(cungKyNamTruoc(kyNam(2026)).nhan).toBe('năm 2025');
  });
});

describe('Kỳ liền trước', () => {
  it('tháng 1 lùi về tháng 12 NĂM TRƯỚC', () => {
    expect(moc(kyLienTruoc(kyThang(2026, 1)))).toEqual(['2025-12-01', '2025-12-31']);
  });
  it('quý 1 lùi về quý 4 năm trước', () => {
    expect(moc(kyLienTruoc(kyQuy(2026, 1)))).toEqual(['2025-10-01', '2025-12-31']);
  });
  it('tháng giữa năm lùi bình thường', () => {
    expect(moc(kyLienTruoc(kyThang(2026, 8)))).toEqual(['2026-07-01', '2026-07-31']);
  });
  it('năm lùi một năm', () => expect(kyLienTruoc(kyNam(2026)).nam).toBe(2025));
});

describe('Kỳ chưa trọn', () => {
  it('đang ở giữa kỳ thì kỳ chưa trọn', () => {
    expect(kyChuaTron(kyThang(2026, 8), new Date(2026, 7, 10, 9))).toBe(true);
  });
  it('kỳ đã đóng thì trọn', () => {
    expect(kyChuaTron(kyThang(2026, 7), new Date(2026, 7, 10))).toBe(false);
  });
  it('ngày 10 là đã trôi 10 ngày, tính cả ngày đầu', () => {
    expect(soNgayDaTroi(kyThang(2026, 8), new Date(2026, 7, 10, 23))).toBe(10);
  });
  it('ngày đầu kỳ là đã trôi 1 ngày, không phải 0', () => {
    expect(soNgayDaTroi(kyThang(2026, 8), new Date(2026, 7, 1, 0, 5))).toBe(1);
  });
  it('mốc trước kỳ thì chưa trôi ngày nào', () => {
    expect(soNgayDaTroi(kyThang(2026, 8), new Date(2026, 6, 20))).toBe(0);
  });
});

describe('Cắt kỳ nền theo tiến độ', () => {
  it('10 ngày đầu của kỳ nền', () => {
    expect(moc(catTheoTienDo(kyThang(2025, 8), 10))).toEqual(['2025-08-01', '2025-08-10']);
  });

  it('nền NGẮN hơn tiến độ thì kẹp ở cuối kỳ nền, không tràn sang tháng sau', () => {
    // Tháng 2/2028 có 29 ngày; trôi 29 ngày; nền tháng 2/2027 chỉ có 28.
    const cat = catTheoTienDo(kyThang(2027, 2), 29);
    expect(moc(cat)).toEqual(['2027-02-01', '2027-02-28']);
  });

  it('trôi đủ kỳ thì trả nguyên kỳ nền, không thêm chú thích thừa', () => {
    const nen = kyThang(2025, 8);
    expect(catTheoTienDo(nen, 31)).toEqual(nen);
  });

  it('cắt 0 ngày thì NÉM LỖI — không trả về một kỳ rỗng trông như kỳ thật', () => {
    expect(() => catTheoTienDo(kyThang(2025, 8), 0)).toThrow();
    expect(() => catTheoTienDo(kyThang(2025, 8), -3)).toThrow();
  });

  it('nhãn nói rõ đã bị cắt — để không ai tưởng đang so với cả tháng', () => {
    expect(catTheoTienDo(kyThang(2025, 8), 10).nhan).toBe('tháng 8/2025 (10 ngày đầu)');
  });
});

describe('Kỳ LŨY KẾ', () => {
  it('lũy kế 8 tháng = từ 1/1 tới hết 31/8', () => {
    expect(moc(kyLuyKe(2026, 8))).toEqual(['2026-01-01', '2026-08-31']);
  });

  it('lũy kế 1 tháng đúng bằng tháng 1', () => {
    expect(moc(kyLuyKe(2026, 1))).toEqual(['2026-01-01', '2026-01-31']);
  });

  it('lũy kế 12 tháng đúng bằng cả năm', () => {
    expect(moc(kyLuyKe(2026, 12))).toEqual(moc(kyNam(2026)));
  });

  it('nhãn nói rõ là lũy kế, không lẫn với một tháng', () => {
    expect(kyLuyKe(2026, 8).nhan).toBe('lũy kế 8 tháng đầu năm 2026');
  });

  /**
   * Đây là chốt làm cho lũy kế đáng làm: nền của nó phải là lũy kế CÙNG ĐỘ DÀI năm trước, chứ
   * không phải cả năm trước. So 8 tháng với 12 tháng thì năm nào cũng "giảm một phần ba".
   */
  it('cùng kỳ năm trước của lũy kế 8 tháng là LŨY KẾ 8 THÁNG năm trước', () => {
    const nen = cungKyNamTruoc(kyLuyKe(2026, 8));
    expect(moc(nen)).toEqual(['2025-01-01', '2025-08-31']);
    expect(nen.nhan).toBe('lũy kế 8 tháng đầu năm 2025');
  });

  it('kỳ liền trước của lũy kế 1 tháng lùi về lũy kế 12 tháng năm trước', () => {
    expect(moc(kyLienTruoc(kyLuyKe(2026, 1)))).toEqual(['2025-01-01', '2025-12-31']);
  });

  it('tháng ngoài dải thì ném lỗi', () => {
    expect(() => kyLuyKe(2026, 0)).toThrow();
    expect(() => kyLuyKe(2026, 13)).toThrow();
  });
});

describe('Kỳ TUỲ CHỌN', () => {
  it('ôm trọn ngày cuối tới 23:59:59.999', () => {
    const k = kyTuyChon(new Date(2026, 2, 5), new Date(2026, 4, 20));
    expect(moc(k)).toEqual(['2026-03-05', '2026-05-20']);
    expect(k.den.getHours()).toBe(23);
  });

  it('nhãn ghi rõ hai đầu, để câu "so với …" không mơ hồ', () => {
    expect(kyTuyChon(new Date(2026, 2, 5), new Date(2026, 4, 20)).nhan).toBe(
      '05/03/2026 – 20/05/2026',
    );
  });

  it('ngày cuối trước ngày đầu thì NÉM LỖI, không lặng lẽ đảo', () => {
    expect(() => kyTuyChon(new Date(2026, 4, 20), new Date(2026, 2, 5))).toThrow();
  });

  /**
   * Ca này TRƯỚC ĐÂY chốt "kỳ tuỳ chọn KHÔNG dịch được — phải chọn nền riêng", với lý lẽ lùi
   * 365 ngày sai vào năm nhuận.
   *
   * Codex bắt hệ quả: người dùng chọn khoảng tự chọn mà để nguyên nền mặc định là báo cáo NÉM
   * LỖI ngay khi họ vừa nhập xong. Và lý lẽ ấy giải sai bài toán — người chọn khoảng tự chọn
   * thường muốn so năm trước hơn ai hết; từ chối chỉ đẩy họ sang tự tính hai ngày rồi nhập tay.
   *
   * Nay lùi cả hai đầu đúng một năm dương lịch, kẹp theo độ dài tháng. Điều làm nó trung thực
   * KHÔNG phải phép kẹp mà là cái NHÃN: nó in ra đúng hai đầu thật, nên người đọc thấy chính
   * xác thứ đã được đem ra so.
   */
  it('cùng kỳ năm trước của khoảng tự chọn = lùi cả hai đầu một năm', () => {
    const k = cungKyNamTruoc(kyTuyChon(new Date(2026, 2, 5), new Date(2026, 4, 20)));
    expect(moc(k)).toEqual(['2025-03-05', '2025-05-20']);
    expect(k.nhan).toBe('05/03/2025 – 20/05/2025');
  });

  it('29/2 năm nhuận lùi về năm thường thì KẸP về 28/2, và nhãn nói ra', () => {
    const k = cungKyNamTruoc(kyTuyChon(new Date(2028, 1, 29), new Date(2028, 2, 10)));
    expect(moc(k)).toEqual(['2027-02-28', '2027-03-10']);
    expect(k.nhan).toBe('28/02/2027 – 10/03/2027');
  });

  it('kỳ liền trước = khoảng CÙNG ĐỘ DÀI nằm ngay trước, không chồng lấn', () => {
    const k = kyLienTruoc(kyTuyChon(new Date(2026, 2, 11), new Date(2026, 2, 20)));
    expect(moc(k)).toEqual(['2026-03-01', '2026-03-10']);
  });

  it('một ngày duy nhất vẫn là kỳ hợp lệ', () => {
    const k = kyTuyChon(new Date(2026, 2, 5), new Date(2026, 2, 5));
    expect(moc(k)).toEqual(['2026-03-05', '2026-03-05']);
  });
});

/**
 * Kỳ báo cáo và các phép dịch kỳ.
 *
 * ── Vì sao mô tả kỳ bằng (loại, năm, số) chứ không bằng cặp ngày ──
 *
 * "Cùng kỳ năm trước" của tháng 2/2028 là tháng 2/2027 — **28 ngày, không phải 29**. Nếu chỉ
 * giữ cặp ngày rồi trừ 365, tháng 2 nhuận sẽ trượt sang ngày 1/3. Giữ nguyên (loại, năm, số)
 * rồi dựng lại cặp ngày từ đó thì phép dịch luôn đúng, không cần biết tháng ấy dài bao nhiêu.
 *
 * ── Múi giờ ──
 *
 * Dùng đúng `new Date(nam, thang - 1, 1)` như `reports.service.ts` vẫn dùng cho kỳ hiện tại.
 * Đây KHÔNG phải lựa chọn về múi giờ mà là ràng buộc về tính nhất quán: kỳ nền phải cắt theo
 * cùng một thước với kỳ hiện tại, nếu không thì chênh lệch đo được một phần là do đổi thước.
 * Đổi múi giờ là việc riêng, phải đổi cả hai chỗ cùng lúc.
 */

export type LoaiKy = 'THANG' | 'QUY' | 'NAM' | 'LUY_KE' | 'TUY_CHON';

export interface Ky {
  loai: LoaiKy;
  nam: number;
  /** Tháng 1-12 hoặc quý 1-4. Không có với kỳ NAM. */
  so?: number;
  tu: Date;
  den: Date;
  /** Nhãn đọc được, dùng thẳng trong câu "so với …". */
  nhan: string;
}

function cuoiNgay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999);
}

export function kyThang(nam: number, thang: number): Ky {
  if (!Number.isInteger(thang) || thang < 1 || thang > 12) {
    throw new Error(`Tháng không hợp lệ: ${thang}`);
  }
  return {
    loai: 'THANG',
    nam,
    so: thang,
    tu: new Date(nam, thang - 1, 1),
    // Ngày 0 của tháng kế = ngày cuối tháng này. Tự đúng với tháng 28/29/30/31 ngày.
    den: cuoiNgay(new Date(nam, thang, 0)),
    nhan: `tháng ${thang}/${nam}`,
  };
}

export function kyQuy(nam: number, quy: number): Ky {
  if (!Number.isInteger(quy) || quy < 1 || quy > 4) {
    throw new Error(`Quý không hợp lệ: ${quy}`);
  }
  const thangDau = (quy - 1) * 3 + 1;
  return {
    loai: 'QUY',
    nam,
    so: quy,
    tu: new Date(nam, thangDau - 1, 1),
    den: cuoiNgay(new Date(nam, thangDau + 2, 0)),
    nhan: `quý ${quy}/${nam}`,
  };
}

export function kyNam(nam: number): Ky {
  return {
    loai: 'NAM',
    nam,
    tu: new Date(nam, 0, 1),
    den: cuoiNgay(new Date(nam, 12, 0)),
    nhan: `năm ${nam}`,
  };
}

function dungLai(loai: LoaiKy, nam: number, so?: number): Ky {
  if (loai === 'THANG') return kyThang(nam, so!);
  if (loai === 'QUY') return kyQuy(nam, so!);
  if (loai === 'LUY_KE') return kyLuyKe(nam, so!);
  return kyNam(nam);
}

/**
 * Lùi một ngày về đúng ngày ấy năm trước, KẸP theo độ dài tháng.
 *
 * 29/02/2028 lùi về 2027 thì không có ngày 29 — kẹp về 28/02/2027. Đây là quy ước, không phải
 * chân lý; điều làm nó trung thực là NHÃN của kỳ nền in ra đúng hai đầu thật, nên người đọc
 * thấy chính xác thứ đã được đem ra so.
 */
function luiMotNam(d: Date): Date {
  const nam = d.getFullYear() - 1;
  const thang = d.getMonth();
  const soNgayCuaThang = new Date(nam, thang + 1, 0).getDate();
  return new Date(nam, thang, Math.min(d.getDate(), soNgayCuaThang));
}

/** Cùng kỳ năm trước — nền mặc định, theo quy ước báo cáo ngành. */
export function cungKyNamTruoc(ky: Ky): Ky {
  if (ky.loai === 'TUY_CHON') {
    // Một khoảng tuỳ ý VẪN có cùng kỳ năm trước dùng được: lùi cả hai đầu đúng một năm dương
    // lịch. Bản đầu từ chối làm việc này, nhưng người chọn khoảng tự chọn thường muốn so năm
    // trước hơn ai hết — từ chối chỉ đẩy họ sang nhập tay hai ngày mà họ tự tính lấy.
    return kyTuyChon(luiMotNam(ky.tu), luiMotNam(ky.den));
  }
  return dungLai(ky.loai, ky.nam - 1, ky.so);
}

/** Kỳ liền trước — tháng trước, quý trước, năm trước; tự lùi năm khi vượt đầu năm. */
export function kyLienTruoc(ky: Ky): Ky {
  if (ky.loai === 'TUY_CHON') {
    // Khoảng CÙNG ĐỘ DÀI nằm ngay trước. Đây là nghĩa duy nhất không mơ hồ của "kỳ liền trước"
    // cho một khoảng tuỳ ý.
    const daiMs = ky.den.getTime() - ky.tu.getTime();
    const denTruoc = new Date(ky.tu.getTime() - 1);
    return kyTuyChon(new Date(denTruoc.getTime() - daiMs), denTruoc);
  }
  if (ky.loai === 'NAM') return kyNam(ky.nam - 1);
  // Số kỳ trong một năm: tháng và lũy kế đều đếm theo tháng (12), quý đếm theo quý (4).
  // Bản đầu viết `loai === 'THANG' ? 12 : 4` nên lũy kế tháng 1 lùi về "lũy kế quý 4" — một kỳ
  // không tồn tại. Khai theo LOẠI, đừng khai theo phủ định của một loại.
  const canh = ky.loai === 'QUY' ? 4 : 12;
  const truoc = ky.so! - 1;
  return truoc >= 1 ? dungLai(ky.loai, ky.nam, truoc) : dungLai(ky.loai, ky.nam - 1, canh);
}

const MOT_NGAY = 86_400_000;

/** Số ngày (tính cả ngày đầu) từ `tu` tới `moc`. Trả 0 khi `moc` còn trước `tu`. */
export function soNgayDaTroi(ky: Ky, moc: Date): number {
  if (moc < ky.tu) return 0;
  const dauMoc = new Date(moc.getFullYear(), moc.getMonth(), moc.getDate());
  return Math.floor((dauMoc.getTime() - ky.tu.getTime()) / MOT_NGAY) + 1;
}

export function kyChuaTron(ky: Ky, moc: Date): boolean {
  return moc < ky.den;
}

/**
 * Cắt kỳ nền cho khớp tiến độ của kỳ hiện tại.
 *
 * Ngày 10 tháng 8 mà đem cả tháng 8 (mới có 10 ngày dữ liệu) so với cả tháng 8 năm ngoái (đủ
 * 31 ngày) thì tháng nào cũng "giảm 68%" — một kết luận sai có hệ thống, và tệ hơn nữa vì nó
 * sai theo hướng nghe như thành tích. Cắt kỳ nền còn đúng 10 ngày đầu thì hai vế mới so được.
 *
 * Kẹp ở `den` của kỳ nền: tháng 2/2028 có 29 ngày, tháng 2/2027 chỉ có 28.
 */
export function catTheoTienDo(kyNen: Ky, soNgay: number): Ky {
  // 0 ngày KHÔNG phải một khoảng nhỏ, mà là không có khoảng nào. Trả `den = tu` thì bộ lọc
  // `gte`/`lte` vẫn đếm được bản ghi ở đúng thời khắc đầu kỳ, và một chênh lệch dựng trên đó
  // trông y hệt số thật. Người gọi phải xử "chưa có nền" trước khi tới đây.
  if (soNgay <= 0) {
    throw new Error(`Không cắt được kỳ nền theo ${soNgay} ngày — kỳ chưa trôi ngày nào.`);
  }
  const cat = cuoiNgay(new Date(kyNen.tu.getTime() + (soNgay - 1) * MOT_NGAY));
  if (cat >= kyNen.den) return kyNen;
  return { ...kyNen, den: cat, nhan: `${kyNen.nhan} (${soNgay} ngày đầu)` };
}

/**
 * Kỳ LŨY KẾ: từ đầu năm tới hết kỳ đang chọn.
 *
 * ── Vì sao là một LOẠI KỲ chứ không phải một kiểu so sánh ──
 *
 * "Lũy kế 8 tháng đầu năm" đổi cả TỬ SỐ lẫn mẫu số: con số hiện trên thẻ phải là tổng 8 tháng,
 * không phải riêng tháng 8. Nếu coi nó là một kiểu SO SÁNH thì thẻ hiện số của tháng 8 mà huy
 * hiệu lại nói về 8 tháng — hai câu về hai kỳ khác nhau đứng cạnh nhau trên một thẻ.
 *
 * Là một loại kỳ thì mọi thứ đi theo: số liệu, huy hiệu, tiêu đề, tệp xuất ra. Và nền so sánh
 * vẫn dùng chung phép cũ — cùng kỳ năm trước của một kỳ lũy kế là kỳ lũy kế cùng độ dài năm
 * trước, tự đúng vì `cungKyNamTruoc` dựng lại từ (loại, năm, số).
 */
export function kyLuyKe(nam: number, denThang: number): Ky {
  if (!Number.isInteger(denThang) || denThang < 1 || denThang > 12) {
    throw new Error(`Tháng không hợp lệ: ${denThang}`);
  }
  return {
    loai: 'LUY_KE',
    nam,
    so: denThang,
    tu: new Date(nam, 0, 1),
    den: cuoiNgay(new Date(nam, denThang, 0)),
    nhan: `lũy kế ${denThang} tháng đầu năm ${nam}`,
  };
}

/**
 * Kỳ do người dùng tự chọn hai đầu.
 *
 * Không có "cùng kỳ năm trước" tự nhiên cho một khoảng tuỳ ý — lùi 365 ngày là sai vào năm
 * nhuận, mà lùi một năm dương lịch thì 29/2 không tồn tại. Nên kỳ tuỳ chọn CHỈ so được với một
 * khoảng nền cũng do người dùng chọn; các phép dịch kỳ từ chối làm việc với nó.
 */
export function kyTuyChon(tu: Date, den: Date): Ky {
  if (den < tu) throw new Error('Khoảng thời gian không hợp lệ: ngày cuối trước ngày đầu.');
  return {
    loai: 'TUY_CHON',
    nam: tu.getFullYear(),
    tu: new Date(tu.getFullYear(), tu.getMonth(), tu.getDate()),
    den: cuoiNgay(den),
    nhan: `${dinhDang(tu)} – ${dinhDang(den)}`,
  };
}

function dinhDang(d: Date): string {
  const hai = (n: number) => String(n).padStart(2, '0');
  return `${hai(d.getDate())}/${hai(d.getMonth() + 1)}/${d.getFullYear()}`;
}

