import { COT_NGAY_TIEP_NHAN, NAM_HOP_LE, ngayHopLe } from './ngay-nghiep-vu';

describe('Cột ngày nghiệp vụ', () => {
  /**
   * Ghim tên cột. Đổi cột là đổi ý nghĩa của MỌI báo cáo kỳ — phải là một quyết định có ý thức,
   * kèm số đo phủ mới, chứ không phải một lần đổi tên biến cho gọn.
   */
  it('mỗi thực thể khai đúng một cột, và là cột đã đo phủ', () => {
    expect(COT_NGAY_TIEP_NHAN).toEqual({
      petition: 'receivedDate',
      incident: 'ngayDeXuat',
      case: 'receiveDate',
    });
  });

  it('KHÔNG thực thể nào dùng createdAt — đó là ngày nhập máy, không phải ngày tiếp nhận', () => {
    expect(Object.values(COT_NGAY_TIEP_NHAN)).not.toContain('createdAt');
  });
});

describe('ngayHopLe', () => {
  it('ngày trong khoảng là hợp lệ', () => {
    expect(ngayHopLe(new Date(2026, 7, 30))).toBe(true);
    expect(ngayHopLe(new Date(NAM_HOP_LE.tu, 0, 1))).toBe(true);
    expect(ngayHopLe(new Date(NAM_HOP_LE.den, 11, 31))).toBe(true);
  });

  it('năm rác của hệ cũ bị loại — đo được 2 hồ sơ năm 225 và 226', () => {
    expect(ngayHopLe(new Date(225, 0, 1))).toBe(false);
    expect(ngayHopLe(new Date(3023, 0, 1))).toBe(false);
  });

  it('không có ngày thì không hợp lệ, và không đổ vỡ', () => {
    expect(ngayHopLe(null)).toBe(false);
    expect(ngayHopLe(undefined)).toBe(false);
  });
});

import { readFileSync } from 'fs';
import { resolve } from 'path';
import { NGAY_TIEP_NHAN_BAT_BUOC, COT_NGAY_TIEP_NHAN as COT } from './ngay-nghiep-vu';

/**
 * Cột BẮT BUỘC thì không được hỏi rỗng.
 *
 * Codex bắt trong chính bản vá này: phép đếm "hồ sơ thiếu ngày" dựng điều kiện bằng khoá động
 * rồi dùng `as never` để bịt lời cảnh báo kiểu. Lời cảnh báo ấy đúng —
 * `Petition.receivedDate` là `DateTime` không cho phép rỗng, nên `{ receivedDate: null }` là
 * điều kiện sai kiểu mà Prisma có thể từ chối LÚC CHẠY, làm hỏng cả endpoint báo cáo. Ép kiểu
 * đã biến một lỗi biên dịch thành một lỗi chỉ hiện ra trên máy thật.
 */
describe('Cột bắt buộc không được hỏi rỗng', () => {
  /**
   * Bóc dòng chú thích trước khi soi. Chú thích trong chính tệp ấy có nhắc `{ receivedDate:
   * null }` để giải thích cái bẫy — và cổng đã bắt trúng câu giải thích ấy. Một cổng tố cáo
   * chính lời cảnh báo của mình là cổng sẽ bị tắt.
   */
  const MA = readFileSync(resolve(__dirname, '../reports.service.ts'), 'utf8')
    .split(String.fromCharCode(10))
    .filter((l) => {
      const t = l.trim();
      return !t.startsWith('//') && !t.startsWith('*') && !t.startsWith('/*');
    })
    .join(String.fromCharCode(10));

  it('lược đồ khai đúng cột nào bắt buộc', () => {
    expect(NGAY_TIEP_NHAN_BAT_BUOC).toEqual({ petition: true, incident: false, case: false });
  });

  it('không truy vấn nào hỏi rỗng trên cột bắt buộc', () => {
    const pham: string[] = [];
    for (const [thucThe, batBuoc] of Object.entries(NGAY_TIEP_NHAN_BAT_BUOC)) {
      if (!batBuoc) continue;
      const cot = COT[thucThe as keyof typeof COT];
      // Không dùng regex: `\s` trong template literal của TypeScript chỉ là chữ `s`, nên
      // mẫu `${cot}\s*:\s*null` lặng lẽ thành `receivedDates*:s*null` và không bao giờ khớp —
      // cổng xanh vì lý do sai. Bỏ hết khoảng trắng rồi so chuỗi thẳng.
      if (MA.replace(/\s/g, '').includes(`${cot}:null`)) pham.push(`${thucThe}.${cot}`);
    }
    expect(pham).toEqual([]);
  });

  /**
   * Và cấm luôn cách né: ép kiểu để bịt trình biên dịch trong chính tệp này. Mỗi lần ép kiểu ở
   * điều kiện truy vấn là một lần đổi lỗi biên dịch lấy lỗi lúc chạy.
   */
  it('không ép kiểu để bịt trình biên dịch trong reports.service.ts', () => {
    // KHÔNG dùng regex ở đây. Hai lần trong cùng một phiên, ký tự thoát bị nuốt lúc sinh
    // tệp và mẫu lặng lẽ thành thứ không bao giờ khớp — cổng xanh vì lý do sai, đúng ở chỗ
    // nó có nhiệm vụ canh. So chuỗi thẳng thì không có gì để nuốt.
    const EP_KIEU = ['as never', 'as any', 'as unknown as'];
    const dong = MA.split(String.fromCharCode(10)).filter((l) =>
      EP_KIEU.some((e) => l.includes(e)),
    );
    expect(dong).toEqual([]);
  });
});

/**
 * Cột ngày nào có nghĩa "hồ sơ ĐẾN trong kỳ này".
 *
 * ── Vì sao không dùng `createdAt` ──
 *
 * Đo trên máy thật ngày 30/08/2026, toàn bộ 54.845 hồ sơ đang có:
 *
 *     petitions  46.741 bản ghi — createdAt: 2026 → 2026   receivedDate:  225 → 2029
 *     incidents   4.723 bản ghi — createdAt: 2026 → 2026   ngayDeXuat:   2006 → 2036
 *     cases       3.381 bản ghi — createdAt: 2026 → 2026   receiveDate:   226 → 2026
 *
 * `createdAt` là NGÀY NHẬP MÁY. Sau đợt di trú, mọi hồ sơ từ 2006 tới nay đều mang createdAt
 * năm 2026. Báo cáo tháng đếm theo cột ấy không đo "hồ sơ đến khi nào" mà đo "cán bộ gõ vào máy
 * khi nào" — nên biểu đồ 12 tháng dồn cục vào tháng di trú, và phép so với cùng kỳ năm trước
 * luôn trả lời "năm ngoái không có hồ sơ nào" trong khi kho đang giữ hồ sơ từ 2006.
 *
 * ── Chọn cột theo SỐ ĐO, không theo tên nghe hay ──
 *
 *     petition.receivedDate    46.741 / 46.741 = 100%    (cột bắt buộc)
 *     incident.ngayDeXuat       4.723 /  4.723 = 100%    Đ.146 BLTTHS — ngày tiếp nhận nguồn tin
 *     case.receiveDate          3.339 /  3.381 = 98,8%
 *
 * Hai ứng viên khác bị loại vì phủ quá thấp: `incident.ngayTiepNhanNguonTin` (64%) và
 * `case.ngay_tiep_nhan` (57%). Chọn cột phủ thấp là lặng lẽ đánh rơi một phần ba số hồ sơ.
 */
export const COT_NGAY_TIEP_NHAN = {
  petition: 'receivedDate',
  incident: 'ngayDeXuat',
  case: 'receiveDate',
} as const;

/**
 * Khoảng năm coi là ngày thật.
 *
 * Đo được 2 hồ sơ trên 54.845 có năm ngoài khoảng (225, 226) — dấu vết ngày gõ hỏng ở hệ cũ.
 * Chúng không rơi vào kỳ nào nên không làm sai con số của kỳ, nhưng phải được ĐẾM RIÊNG chứ
 * không được biến mất: một hồ sơ không lọt vào báo cáo nào là một hồ sơ vô hình.
 *
 * Cùng khoảng với cột sinh `sortReceivedDate` ở `schema.prisma` — một luật, một chỗ hiểu.
 */
export const NAM_HOP_LE = { tu: 1900, den: 2100 } as const;

export function ngayHopLe(d: Date | null | undefined): boolean {
  if (!d) return false;
  const n = d.getFullYear();
  return n >= NAM_HOP_LE.tu && n <= NAM_HOP_LE.den;
}

/**
 * Cột ngày tiếp nhận có BẮT BUỘC hay không.
 *
 * `Petition.receivedDate` là `DateTime` không cho phép rỗng, nên hỏi Prisma `{ receivedDate:
 * null }` là một điều kiện sai kiểu — và một bản vá dùng `as never` để bịt lời cảnh báo ấy đã
 * lọt tới tận vòng soát. Khai ra ở đây để phép đếm "hồ sơ thiếu ngày" tự biết bảng nào cần hỏi
 * rỗng, bảng nào thì hỏi là vô nghĩa.
 */
export const NGAY_TIEP_NHAN_BAT_BUOC = {
  petition: true,
  incident: false,
  case: false,
} as const;

/** Mốc đầu và cuối của khoảng năm coi là ngày thật. */
export const MOC_NAM_HOP_LE = {
  dau: new Date(NAM_HOP_LE.tu, 0, 1),
  cuoi: new Date(NAM_HOP_LE.den, 11, 31, 23, 59, 59, 999),
};

