/**
 * TdacExportService Unit Tests
 *
 * export():
 *   - throws ServiceUnavailableException when template file is not found
 *   - throws ServiceUnavailableException when workbook has no worksheets
 *   - fills total and team cells for each data row
 *   - sets Content-Type and Content-Disposition headers on the response
 *   - skips rows with unknown rowKey (no crash)
 */

import { ServiceUnavailableException } from '@nestjs/common';
import { TdacExportService } from './tdac-export.service';

// ─── Mock fs ──────────────────────────────────────────────────────────────────

jest.mock('fs', () => ({
  existsSync: jest.fn().mockReturnValue(true),
}));

import * as fs from 'fs';
const mockExistsSync = fs.existsSync as jest.Mock;

// ─── Mock ExcelJS ─────────────────────────────────────────────────────────────

const mockCell = { value: null as unknown };

const mockWorksheet = {
  getCell: jest.fn().mockReturnValue(mockCell),
};

const mockWorkbook = {
  xlsx: {
    readFile: jest.fn().mockResolvedValue(undefined),
    write: jest.fn().mockResolvedValue(undefined),
  },
  worksheets: [mockWorksheet] as typeof mockWorksheet[],
};

jest.mock('exceljs', () => ({
  Workbook: jest.fn().mockImplementation(() => mockWorkbook),
}));

// ─── Mock Response ────────────────────────────────────────────────────────────

function makeRes() {
  return {
    setHeader: jest.fn(),
    status: jest.fn().mockReturnThis(),
    json: jest.fn(),
  } as any;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function makeDraft(overrides: Record<string, unknown> = {}) {
  return {
    id: 'draft-1',
    loaiBaoCao: 'VU_AN',
    computedData: {
      rows: [
        { rowKey: '1', total: 10, byTeam: [{ teamId: 'to4', value: 4 }, { teamId: 'to5', value: 6 }] },
        { rowKey: '2', total: 5, byTeam: [{ teamId: 'to4', value: 2 }, { teamId: 'to5', value: 3 }] },
      ],
    },
    adjustedData: null,
    ...overrides,
  } as any;
}

// ─── Test Suite ───────────────────────────────────────────────────────────────

describe('TdacExportService', () => {
  let service: TdacExportService;

  beforeEach(() => {
    service = new TdacExportService();
    jest.clearAllMocks();
    mockExistsSync.mockReturnValue(true);
    mockWorkbook.xlsx.readFile.mockResolvedValue(undefined);
    mockWorkbook.xlsx.write.mockResolvedValue(undefined);
    mockWorkbook.worksheets = [mockWorksheet];
    mockWorksheet.getCell.mockReturnValue({ value: null });
  });

  // ── export ─────────────────────────────────────────────────────────────────

  it('throws ServiceUnavailableException when template file is not found', async () => {
    mockExistsSync.mockReturnValue(false);

    await expect(service.export(makeDraft(), makeRes())).rejects.toThrow(
      ServiceUnavailableException,
    );
  });

  it('throws ServiceUnavailableException when workbook has no worksheets', async () => {
    mockWorkbook.worksheets = [];

    await expect(service.export(makeDraft(), makeRes())).rejects.toThrow(
      ServiceUnavailableException,
    );
  });

  it('fills total cell (column C) and team cells (D, E) for known rowKeys', async () => {
    const cells: Record<string, { value: unknown }> = {};
    mockWorksheet.getCell.mockImplementation((addr: string) => {
      if (!cells[addr]) cells[addr] = { value: null };
      return cells[addr];
    });

    await service.export(makeDraft(), makeRes());

    // rowKey '1' maps to Excel row 8 → C8=total, D8=team0, E8=team1
    expect(cells['C8']?.value).toBe(10);
    expect(cells['D8']?.value).toBe(4);
    expect(cells['E8']?.value).toBe(6);
    // rowKey '2' → row 9
    expect(cells['C9']?.value).toBe(5);
  });

  it('sets Content-Type and Content-Disposition headers on the response', async () => {
    const res = makeRes();
    await service.export(makeDraft(), res);

    expect(res.setHeader).toHaveBeenCalledWith(
      'Content-Type',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    );
    expect(res.setHeader).toHaveBeenCalledWith(
      'Content-Disposition',
      expect.stringContaining('attachment'),
    );
  });

  it('prefers adjustedData over computedData when both present', async () => {
    const cells: Record<string, { value: unknown }> = {};
    mockWorksheet.getCell.mockImplementation((addr: string) => {
      if (!cells[addr]) cells[addr] = { value: null };
      return cells[addr];
    });

    const draft = makeDraft({
      adjustedData: {
        rows: [{ rowKey: '1', total: 99, byTeam: [] }],
      },
      computedData: {
        rows: [{ rowKey: '1', total: 1, byTeam: [] }],
      },
    });

    await service.export(draft, makeRes());

    // adjustedData wins → C8 = 99
    expect(cells['C8']?.value).toBe(99);
  });

  it('does not crash when rows contain unknown rowKeys', async () => {
    const draft = makeDraft({
      computedData: {
        rows: [{ rowKey: 'UNKNOWN_KEY', total: 5, byTeam: [] }],
      },
    });

    await expect(service.export(draft, makeRes())).resolves.not.toThrow();
  });
});

import { Injectable, Logger, OnModuleInit, ServiceUnavailableException } from '@nestjs/common';
import { Response } from 'express';
import * as path from 'path';
import * as fs from 'fs';
import * as ExcelJS from 'exceljs';
import { ReportTdcDraft } from '@prisma/client';

const TEMPLATE_DIR = path.resolve(__dirname, '../../../../assets/templates');
const TEMPLATES: Record<string, string> = {
  VU_AN: path.join(TEMPLATE_DIR, 'phu-luc-08-vu-an.xlsx'),
  VU_VIEC: path.join(TEMPLATE_DIR, 'phu-luc-08-vu-viec.xlsx'),
};

// Cell mapping: rowKey → { total: cellAddress, byTeamIndex: cellAddress[] }
// Teams are assumed in order: Tổ4 (col D), Tổ5 (col E), Tổ10 (col F)
// Starting Excel row = 8 for row 1, then increments
const ROW_TO_EXCEL_ROW: Record<string, number> = {
  '1': 8,
  '2': 9,
  '2.1': 10,
  '2.2': 11,
  '2.3': 12,
  '2.4': 13,
  '2.5': 14,
  '2.6': 15,
  '2.7': 16,
  '2.8': 17,
  '3': 18,
  '3.1': 19,
  '3.2': 20,
  '3.3': 21,
  '3.3.1': 22,
  '3.3.2': 23,
  '3.3.3': 24,
  '3.3.4': 25,
  '3.3.5': 26,
  '4': 27,
  '5': 28,
  '5.1': 29,
  '5.2': 30,
  '5.3': 31,
  '5.4': 32,
  '5.5': 33,
  '5.6.1': 34,
  '5.6.2': 35,
  '5.6.3': 36,
  '5.6.4': 37,
  '5.6.5': 38,
  '5.6.6': 39,
  '5.6.7': 40,
  '5.6.8': 41,
};

// Column mapping: total=C, team[0]=D, team[1]=E, team[2]=F
const COL_TOTAL = 'C';
const TEAM_COLS = ['D', 'E', 'F'];

@Injectable()
export class TdacExportService implements OnModuleInit {
  private readonly logger = new Logger(TdacExportService.name);

  onModuleInit() {
    for (const [type, templatePath] of Object.entries(TEMPLATES)) {
      if (!fs.existsSync(templatePath)) {
        this.logger.warn(
          `Template file not found for ${type}: ${templatePath}. Export will be unavailable until the file is added.`,
        );
      } else {
        this.logger.log(`Template verified: ${templatePath}`);
      }
    }
  }

  async export(draft: ReportTdcDraft, res: Response): Promise<void> {
    const loaiBaoCao = draft.loaiBaoCao as string;
    const templatePath = TEMPLATES[loaiBaoCao];

    if (!templatePath || !fs.existsSync(templatePath)) {
      throw new ServiceUnavailableException(
        `Template file not found for ${loaiBaoCao}. Please contact system administrator.`,
      );
    }

    // Use adjustedData if available, else fall back to computedData
    const data = (draft.adjustedData ?? draft.computedData) as {
      rows?: Array<{
        rowKey: string;
        total: number;
        byTeam: Array<{ teamId: string; value: number }>;
      }>;
    };

    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.readFile(templatePath);

    const worksheet = workbook.worksheets[0];
    if (!worksheet) {
      throw new ServiceUnavailableException('Template file is invalid: no worksheets found');
    }

    // Fill cells
    if (data?.rows && Array.isArray(data.rows)) {
      for (const row of data.rows) {
        const excelRow = ROW_TO_EXCEL_ROW[row.rowKey];
        if (!excelRow) continue;

        // Total column
        const totalCell = worksheet.getCell(`${COL_TOTAL}${excelRow}`);
        totalCell.value = row.total ?? 0;

        // Team columns
        if (Array.isArray(row.byTeam)) {
          row.byTeam.forEach((teamEntry, idx) => {
            if (idx >= TEAM_COLS.length) return;
            const col = TEAM_COLS[idx];
            const cell = worksheet.getCell(`${col}${excelRow}`);
            cell.value = teamEntry.value ?? 0;
          });
        }
      }
    }

    const filename = `phu-luc-08-${loaiBaoCao.toLowerCase().replace(/_/g, '-')}-${Date.now()}.xlsx`;
    res.setHeader(
      'Content-Type',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    );
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);

    await workbook.xlsx.write(res);
  }
}

