      );

      expect(mockPrisma.notification.create).not.toHaveBeenCalled();
    });

    it('catches exceptions without rethrowing', async () => {
      mockPrisma.notificationPreference.findUnique.mockRejectedValue(new Error('DB down'));

      await expect(
        service.onIncidentAssigned(
          new IncidentAssignedEvent('inc-1', 'Vụ cướp', 'user-b', 'user-a', 'Admin'),
