  describe('onUydtAssigned', () => {
    it('fans out to both toUserId and toLeaderUserIds', async () => {
      await service.onUydtAssigned(
        new UydtAssignedEvent('del-1', 'UTDT-001', 'assignee-1', ['leader-1', 'leader-2'], 'user-a', 'Admin'),
