import { TestingModule, Test } from '@nestjs/testing';
import { NotificationSseService } from './notification-sse.service';
import { Subscription, take } from 'rxjs';

describe('NotificationSseService', () => {
  let service: NotificationSseService;
  let subscriptions: Subscription;

  beforeEach(async () => {
    subscriptions = new Subscription();
    const module: TestingModule = await Test.createTestingModule({
      providers: [NotificationSseService],
    }).compile();
    service = module.get<NotificationSseService>(NotificationSseService);
  });

  afterEach(() => {
    subscriptions.unsubscribe();
    service.onModuleDestroy();
  });

  it('emits an event to a subscribed user when notifyUser is called', (done) => {
    const stream$ = service.createStream('user-1');
    stream$.pipe(take(1)).subscribe({
      next: (event) => {
        expect(event).toBeDefined();
        expect(event.data).toMatchObject({ type: 'unread-count-update' });
        done();
      },
      error: done,
    });
    service.notifyUser('user-1');
  });

  it('emits to all tabs of the same user when notifyUser is called', (done) => {
    let received = 0;
    const onNext = () => {
      received++;
      if (received === 2) {
        expect(received).toBe(2);
        done();
      }
    };

    service
      .createStream('user-1')
      .pipe(take(1))
      .subscribe({ next: onNext, error: done });
    service
      .createStream('user-1')
      .pipe(take(1))
      .subscribe({ next: onNext, error: done });

    service.notifyUser('user-1');
  });

  it('does not emit to a different user when notifyUser is called', (done) => {
    let user2Received = false;
    subscriptions.add(
      service
        .createStream('user-2')
        .pipe(take(1))
        .subscribe({
          next: () => {
            user2Received = true;
          },
          error: done,
        }),
    );

    service.notifyUser('user-1');

    // Give it a tick — if user-2 received anything, the flag would be set
    setTimeout(() => {
      expect(user2Received).toBe(false);
      done();
    }, 50);
  });

  it('cleans up internal state when a client stream is unsubscribed', (done) => {
    const sub = service.createStream('user-1').subscribe();
    // Force subscription to exist
    setTimeout(() => {
      sub.unsubscribe();
      // After unsubscribe the stream map entry should be cleaned up
      service.notifyUser('user-1'); // should not throw
      done();
    }, 10);
  });

  it('completes all streams on module destroy without throwing', () => {
    subscriptions.add(service.createStream('user-a').subscribe());
    subscriptions.add(service.createStream('user-b').subscribe());
    expect(() => service.onModuleDestroy()).not.toThrow();
  });
});

import { Injectable, OnModuleDestroy, MessageEvent } from '@nestjs/common';
import { Subject, Observable, merge, interval } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class NotificationSseService implements OnModuleDestroy {
  // Map<userId, Set<Subject>> — support multiple tabs per user
  private readonly streams = new Map<string, Set<Subject<void>>>();

  /** Called by NotificationEventService after creating a notification */
  notifyUser(userId: string): void {
    this.streams.get(userId)?.forEach((s) => s.next());
  }

  /** Called by SseController to create a per-tab stream */
  createStream(userId: string): Observable<MessageEvent> {
    const subject = new Subject<void>();
    if (!this.streams.has(userId)) this.streams.set(userId, new Set());
    this.streams.get(userId)!.add(subject);

    const notify$ = subject.pipe(
      map(() => ({ data: { type: 'unread-count-update' } } as MessageEvent)),
    );

    // D4: heartbeat every 30s — keeps connection alive through NAT/firewall
    const heartbeat$ = interval(30_000).pipe(
      map(() => ({ data: { type: 'heartbeat' } } as MessageEvent)),
    );

    return new Observable<MessageEvent>((observer) => {
      const sub = merge(notify$, heartbeat$).subscribe(observer);

      return () => {
        sub.unsubscribe();
        this.streams.get(userId)?.delete(subject);
        if (this.streams.get(userId)?.size === 0) {
          this.streams.delete(userId);
        }
      };
    });
  }

  onModuleDestroy(): void {
    this.streams.forEach((set) => set.forEach((s) => s.complete()));
    this.streams.clear();
  }
}

