/**
 * NotificationsService Unit Tests
 *
 * getList:
 *   - returns { success, data, total, unreadCount, limit, offset }
 *   - filters by unreadOnly flag
 *
 * markAsRead:
 *   - returns success: false when notification not found
 *   - skips update when already read, returns existing record
 *   - updates isRead=true and calls prisma.notification.update
 *
 * markAllAsRead:
 *   - calls updateMany and returns updatedCount
 */

import { Test, TestingModule } from '@nestjs/testing';
import { NotificationsService } from './notifications.service';
import { PrismaService } from '../prisma/prisma.service';

// ─── Mock Prisma ──────────────────────────────────────────────────────────────

const mockPrisma = {
  notification: {
    findMany: jest.fn().mockResolvedValue([]),
    count: jest.fn().mockResolvedValue(0),
    findFirst: jest.fn().mockResolvedValue(null),
    update: jest.fn(),
    updateMany: jest.fn().mockResolvedValue({ count: 0 }),
    delete: jest.fn(),
    deleteMany: jest.fn().mockResolvedValue({ count: 0 }),
    create: jest.fn(),
    createMany: jest.fn(),
  },
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function makeNotification(overrides: Record<string, unknown> = {}) {
  return {
    id: 'notif-1',
    userId: 'user-1',
    type: 'SYSTEM',
    title: 'Test notification',
    message: 'Test message',
    isRead: false,
    readAt: null,
    link: null,
    metadata: null,
    createdAt: new Date(),
    // D10 fields (added in notification-center migration)
    acknowledgedAt: null,
    pushNextRetryAt: null,
    pushRetryCount: 0,
    pushSentAt: null,
    pushMaxRetries: 3,
    ...overrides,
  };
}

// ─── Test Suite ───────────────────────────────────────────────────────────────

describe('NotificationsService', () => {
  let service: NotificationsService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [
        NotificationsService,
        { provide: PrismaService, useValue: mockPrisma },
      ],
    }).compile();

    service = module.get<NotificationsService>(NotificationsService);
    jest.clearAllMocks();
    mockPrisma.notification.findMany.mockResolvedValue([]);
    mockPrisma.notification.count.mockResolvedValue(0);
    mockPrisma.notification.findFirst.mockResolvedValue(null);
    mockPrisma.notification.update.mockResolvedValue(makeNotification({ isRead: true }));
    mockPrisma.notification.updateMany.mockResolvedValue({ count: 0 });
    mockPrisma.notification.delete.mockResolvedValue({});
    mockPrisma.notification.deleteMany.mockResolvedValue({ count: 0 });
  });

  // ── getList ────────────────────────────────────────────────────────────────

  describe('getList', () => {
    it('returns required response shape', async () => {
      mockPrisma.notification.findMany.mockResolvedValue([makeNotification()]);
      mockPrisma.notification.count
        .mockResolvedValueOnce(1)  // total
        .mockResolvedValueOnce(1); // unreadCount

      const result = await service.getList('user-1', { limit: 20, offset: 0 });

      expect(result).toHaveProperty('success', true);
      expect(result).toHaveProperty('data');
      expect(result).toHaveProperty('total', 1);
      expect(result).toHaveProperty('unreadCount', 1);
      expect(result).toHaveProperty('limit', 20);
      expect(result).toHaveProperty('offset', 0);
      expect(Array.isArray(result.data)).toBe(true);
    });

    it('passes unreadOnly:true filter to Prisma when requested', async () => {
      await service.getList('user-1', { unreadOnly: true, limit: 20, offset: 0 });

      const callArgs = mockPrisma.notification.findMany.mock.calls[0][0];
      expect(callArgs.where).toMatchObject({ userId: 'user-1', isRead: false });
    });

    it('does not add isRead filter when unreadOnly is false', async () => {
      await service.getList('user-1', { unreadOnly: false, limit: 20, offset: 0 });

      const callArgs = mockPrisma.notification.findMany.mock.calls[0][0];
      expect(callArgs.where).not.toHaveProperty('isRead');
    });
  });

  // ── markAsRead ─────────────────────────────────────────────────────────────

  describe('markAsRead', () => {
    it('returns success: false when notification not found', async () => {
      mockPrisma.notification.findFirst.mockResolvedValue(null);

      const result = await service.markAsRead('notif-missing', 'user-1');

      expect(result.success).toBe(false);
      expect(result).toHaveProperty('message', 'Notification not found');
      expect(mockPrisma.notification.update).not.toHaveBeenCalled();
    });

    // D10 fix: update must always be called — even when isRead=true —
    // so that acknowledgedAt is set and pushNextRetryAt is cleared.
    it('still calls update with acknowledgedAt when notification is already read (D10 fix)', async () => {
      const alreadyRead = makeNotification({ isRead: true, readAt: new Date() });
      const updated = makeNotification({ isRead: true, acknowledgedAt: new Date(), pushNextRetryAt: null });
      mockPrisma.notification.findFirst.mockResolvedValue(alreadyRead);
      mockPrisma.notification.update.mockResolvedValue(updated);

      const result = await service.markAsRead('notif-1', 'user-1');

      expect(result.success).toBe(true);
      // update must be called even though isRead was already true
      expect(mockPrisma.notification.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: 'notif-1' },
          data: expect.objectContaining({
            acknowledgedAt: expect.any(Date),
            pushNextRetryAt: null,
          }),
        }),
      );
    });

    it('calls prisma.update with isRead=true + acknowledgedAt + pushNextRetryAt=null when unread', async () => {
      const unread = makeNotification({ isRead: false });
      mockPrisma.notification.findFirst.mockResolvedValue(unread);
      const updated = makeNotification({ isRead: true, acknowledgedAt: new Date(), pushNextRetryAt: null });
      mockPrisma.notification.update.mockResolvedValue(updated);

      const result = await service.markAsRead('notif-1', 'user-1');

      expect(mockPrisma.notification.update).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { id: 'notif-1' },
          data: expect.objectContaining({
            isRead: true,
            acknowledgedAt: expect.any(Date),
            pushNextRetryAt: null,
          }),
        }),
      );
      expect(result.success).toBe(true);
      expect(result.data).toBe(updated);
    });
  });

  // ── markAllAsRead ──────────────────────────────────────────────────────────

  describe('markAllAsRead', () => {
    it('calls updateMany for the given user and returns updatedCount', async () => {
      mockPrisma.notification.updateMany.mockResolvedValue({ count: 3 });

      const result = await service.markAllAsRead('user-1');

      expect(mockPrisma.notification.updateMany).toHaveBeenCalledWith(
        expect.objectContaining({
          where: { userId: 'user-1', isRead: false },
          data: expect.objectContaining({
            isRead: true,
            acknowledgedAt: expect.any(Date),
            pushNextRetryAt: null,
          }),
        }),
      );
      expect(result).toHaveProperty('success', true);
      expect(result).toHaveProperty('updatedCount', 3);
    });

    it('returns updatedCount: 0 when no unread notifications exist', async () => {
      mockPrisma.notification.updateMany.mockResolvedValue({ count: 0 });

      const result = await service.markAllAsRead('user-1');

      expect(result.updatedCount).toBe(0);
    });
  });
});

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateNotificationDto } from './dto/create-notification.dto';
import { QueryNotificationsDto } from './dto/query-notifications.dto';
import { Prisma } from '@prisma/client';

@Injectable()
export class NotificationsService {
  constructor(private readonly prisma: PrismaService) {}

  // ── GET LIST ────────────────────────────────────────────────────────────
  async getList(userId: string, query: QueryNotificationsDto) {
    const { unreadOnly, limit = 20, offset = 0 } = query;

    const where: Prisma.NotificationWhereInput = {
      userId,
      ...(unreadOnly ? { isRead: false } : {}),
    };

    const [data, total, unreadCount] = await Promise.all([
      this.prisma.notification.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      }),
      this.prisma.notification.count({ where }),
      this.prisma.notification.count({ where: { userId, isRead: false } }),
    ]);

    return {
      success: true,
      data,
      total,
      unreadCount,
      limit,
      offset,
    };
  }

  // ── GET UNREAD COUNT ─────────────────────────────────────────────────────
  async getUnreadCount(userId: string) {
    const count = await this.prisma.notification.count({
      where: { userId, isRead: false },
    });
    return { success: true, unreadCount: count };
  }

  // ── MARK ONE AS READ ─────────────────────────────────────────────────────
  async markAsRead(id: string, userId: string) {
    const notification = await this.prisma.notification.findFirst({
      where: { id, userId },
    });
    if (!notification) {
      return { success: false, message: 'Notification not found' };
    }
    // D10: always set acknowledgedAt + clear pushNextRetryAt, regardless of isRead state.
    // Clicking the notification link = user acknowledged the assignment.
    // Removing the early-return prevents infinite push retries when notification
    // was read via dropdown (isRead=true) but never clicked (acknowledgedAt never set).
    const now = new Date();
    const updated = await this.prisma.notification.update({
      where: { id },
      data: {
        isRead: true,
        readAt: (notification as Record<string, unknown>).readAt as Date | null ?? now,
        acknowledgedAt: (notification as Record<string, unknown>).acknowledgedAt as Date | null ?? now,
        pushNextRetryAt: null,
      },
    });
    return { success: true, data: updated };
  }

  // ── MARK ALL AS READ ─────────────────────────────────────────────────────
  async markAllAsRead(userId: string) {
    const result = await this.prisma.notification.updateMany({
      where: { userId, isRead: false },
      data: { isRead: true, readAt: new Date(), acknowledgedAt: new Date(), pushNextRetryAt: null },
    });
    return { success: true, updatedCount: result.count };
  }

  // ── DELETE ONE ───────────────────────────────────────────────────────────
  async deleteOne(id: string, userId: string) {
    const notification = await this.prisma.notification.findFirst({
      where: { id, userId },
    });
    if (!notification) {
      return { success: false, message: 'Notification not found' };
    }
    await this.prisma.notification.delete({ where: { id } });
    return { success: true };
  }

  // ── DELETE ALL READ ──────────────────────────────────────────────────────
  async deleteAllRead(userId: string) {
    const result = await this.prisma.notification.deleteMany({
      where: { userId, isRead: true },
    });
    return { success: true, deletedCount: result.count };
  }

  // ── CREATE (internal use — called by other services) ─────────────────────
  async create(dto: CreateNotificationDto) {
    const notification = await this.prisma.notification.create({
      data: {
        userId: dto.userId,
        type: dto.type,
        title: dto.title,
        message: dto.message,
        link: dto.link,
        metadata: dto.metadata as Prisma.InputJsonValue ?? Prisma.JsonNull,
      },
    });
    return notification;
  }
}

